        _removeTokenLiquidity(token, shares, minTokenAmount, epoch);
    }

    /**
     * @notice Remove token liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minTokenAmount Minimum amount of tokens to receive
     * @param epoch Epoch to remove liquidity from
     */
    function _removeTokenLiquidity(
        address token,
        uint256 shares,
        uint256 minTokenAmount,
        uint256 epoch
    ) internal {
        TokenPoolInfo storage pool = tokenPools[token][epoch];
        TokenProvider storage provider = tokenProviders[token][msg.sender][
            epoch
        ];

        require(pool.totalLPShares > 0, "No token liquidity in pool");
        require(provider.tokenAmount > 0, "No token liquidity to withdraw");

        // Calculate pending token rewards before withdrawing
        uint256 pendingTokens = (provider.lpShares * pool.accRewardPerShare) /
            SCALE -
            provider.rewardDebt;
        provider.pendingReward += pendingTokens;

        // Calculate pending ETH rewards before withdrawing
        uint256 pendingEth = (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE -
            provider.ethRewardDebt;
        provider.pendingETHReward += pendingEth;

        uint256 lpSharesToBurn;

        lpSharesToBurn = (provider.lpShares * shares) / 10000;
        require(lpSharesToBurn > 0, "No shares to burn");
        require(
            lpSharesToBurn <= provider.lpShares,
            "Insufficient shares to burn"
        );

        // Calculate actual withdrawal amounts based on LP shares
        uint256 actualTokenWithdraw = _calculateWithdrawalAmount(
            lpSharesToBurn,
            pool.totalTokens,
            pool.totalLPShares
        );
        require(
            actualTokenWithdraw <= pool.totalTokens,
            "Insufficient tokens in pool"
        );

        // Update balances
        provider.tokenAmount -= actualTokenWithdraw;
        provider.lpShares -= lpSharesToBurn;

        // Calculate accounted values BEFORE reducing totalLPShares
        uint256 accountedTokenToRemove = (pool.accountedToken *
            lpSharesToBurn) / pool.totalLPShares;

        pool.totalTokens -= actualTokenWithdraw;
        pool.totalLPShares -= lpSharesToBurn;
        pool.accountedToken -= accountedTokenToRemove;

        // Update reward debt for remaining shares
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.ethRewardDebt =
            (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE;

        // Transfer tokens back to user
        require(
            actualTokenWithdraw >= minTokenAmount,
            "Insufficient token withdrawn"
        );
        IERC20(token).safeTransfer(msg.sender, actualTokenWithdraw);

        // Transfer accumulated ETH rewards to user
        if (provider.pendingETHReward > 0) {
            uint256 ethRewards = provider.pendingETHReward;
            provider.pendingETHReward = 0;
            (bool success, ) = payable(msg.sender).call{value: ethRewards}("");
            require(success, "ETH reward transfer failed");

            emit PoolSharesClaimed(msg.sender, ethRewards, token, epoch, true);
        }

        // Track total tokens removed by LPs
        totalTokensRemoved[token] += actualTokenWithdraw;

        emit TokenLiquidityWithdrawn(
            msg.sender,
            token,
            epoch,
            actualTokenWithdraw,
            lpSharesToBurn
        );
    }

    /**
     * @notice Execute buy order - Orderbook sends ETH, receives tokens
     * @param token The token being bought
     * @param ethAmount Amount of ETH sent by orderbook
     * @param tokenAmount Amount of tokens to send to orderbook
     * @dev Only callable by the orderbook contract
     */
    function executeBuyOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external payable isNotBlocked(token) onlyOrderbook {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(tokenAmount > 0, "Token amount must be greater than 0");
        require(msg.value == ethAmount, "ETH amount mismatch");

        TokenPoolInfo storage tokenPool = tokenPools[token][
            currentTokenEpochs[token]
        ];
        require(
            tokenPool.totalTokens >= tokenAmount,
            "Insufficient token liquidity"
        );

        // Token pool provides tokens to orderbook
        tokenPool.totalTokens -= tokenAmount;
        totalTokensRemoved[token] += tokenAmount;
        // Token pool receives ETH rewards for providing tokens
        _updateTokenPoolETHRewards(token, ethAmount);

        // Transfer tokens to orderbook
        IERC20(token).safeTransfer(msg.sender, tokenAmount);

        // Check if token pool is empty and increment token epoch if needed
        _checkAndIncrementTokenEpoch(token);

        emit PoolBalanceUpdated(
            token,
            ethPools[token][currentETHEpochs[token]].totalETH,
            tokenPool.totalTokens,
            ethPools[token][currentETHEpochs[token]].totalLPShares,
            tokenPool.totalLPShares,
            currentETHEpochs[token]
        );
    }

    /**
     * @notice Execute sell order - Orderbook sends tokens, receives ETH
     * @param token The token being sold
     * @param ethAmount Amount of ETH to send to orderbook
     * @param tokenAmount Amount of tokens sent by orderbook
     * @dev Only callable by the orderbook contract
     */
    function executeSellOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external isNotBlocked(token) onlyOrderbook {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(tokenAmount > 0, "Token amount must be greater than 0");

        ETHPoolInfo storage ethPool = ethPools[token][currentETHEpochs[token]];
        require(ethPool.totalETH >= ethAmount, "Insufficient ETH liquidity");

        // Transfer tokens from orderbook to market maker pool
        IERC20(token).safeTransferFrom(msg.sender, address(this), tokenAmount);

        // ETH pool provides ETH to orderbook
        ethPool.totalETH -= ethAmount;
        totalEthRemoved += ethAmount;

        // ETH pool receives token rewards for providing ETH
        _updateETHPoolTokenRewards(token, tokenAmount);

        // Transfer ETH to orderbook
        (bool success, ) = payable(msg.sender).call{value: ethAmount}("");
        require(success, "ETH transfer to orderbook failed");

        // Check if ETH pool is empty and increment ETH epoch if needed
        _checkAndIncrementETHEpoch(token);

        emit PoolBalanceUpdated(
            token,
            ethPool.totalETH,
            tokenPools[token][currentTokenEpochs[token]].totalTokens,
            ethPool.totalLPShares,
            tokenPools[token][currentTokenEpochs[token]].totalLPShares,
            currentTokenEpochs[token]
        );
    }

    /// @notice Distributes fee distribution from orderbook to be distributed to market makers
    /// @param token Address of the token pool to distribute fees for
    /// @param epoch Epoch to distribute fee.
    /// @param isETHPool Whether to distribute to ETH pool (true) or token pool (false)
    function distributePoolFee(
        address token,
        uint256 epoch,
        bool isETHPool
    ) external payable onlyRewardDistributor {
        require(msg.value > 0, "No ETH sent");

        if (isETHPool) {
            ETHPoolInfo storage pool = ethPools[token][epoch];
            require(pool.totalLPShares > 0, "No ETH liquidity");
            _updateETHPool(token, epoch, msg.value);
        } else {
            TokenPoolInfo storage pool = tokenPools[token][epoch];
            require(pool.totalLPShares > 0, "No token liquidity");
            _updateTokenPool(token, epoch, msg.value);
        }

        emit PoolFeeDistributed(msg.sender, msg.value, token, epoch, isETHPool);
    }

    /**
     * @notice Claim all epochs pool fees for a token
     * @param token Address of the token pool to claim rewards from
     * @param epochs Epochs to claim rewards from
     * @param isETHPool Whether to claim ETH pool fees (true) or token pool fees (false)
     */
    function claimAllEpochsPoolFee(
        address token,
        uint256[] memory epochs,
        bool isETHPool
    ) external nonReentrant {
        for (uint256 i = 0; i < epochs.length; i++) {
            if (isETHPool) {
                _claimEthPoolFee(token, epochs[i]);
            } else {
                _claimEthFeeFromTokenPool(token, epochs[i]);
            }
        }
    }

    /// @notice Claim ETH rewards for ETH providers
    /// @param token Address of the token pool to claim rewards from
    /// @param epoch Epoch to claim rewards from
    function claimEthPoolFee(
        address token,
        uint256 epoch
    ) external nonReentrant {
        _claimEthPoolFee(token, epoch);
    }

    /**
     * @notice Claim ETH rewards for ETH providers
     * @param token Address of the token pool to claim rewards from
     * @param epoch Epoch to claim rewards from
     */
    function _claimEthPoolFee(address token, uint256 epoch) internal {
        ETHPoolInfo storage pool = ethPools[token][epoch];
        ETHProvider storage provider = ethProviders[token][msg.sender][epoch];

        require(
            provider.lpShares > 0 || provider.pendingReward > 0,
            "No liquidity or rewards"
        );

        uint256 accumulated = (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        uint256 reward = accumulated -
            provider.rewardDebt +
            provider.pendingReward;
        require(reward > 0, "No rewards");

        provider.rewardDebt = accumulated;
        provider.pendingReward = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "ETH transfer failed");

        emit FeeClaimedFromEthPool(msg.sender, reward, token, epoch);
    }

    /// @notice Claim token rewards for token providers
    /// @param token Address of the token pool to claim rewards from
    /// @param epoch Epoch to claim rewards from
    function claimEthFeeFromTokenPool(
        address token,
        uint256 epoch
    ) external nonReentrant {
        _claimEthFeeFromTokenPool(token, epoch);
    }

    /**
     * @notice Claim token rewards for token providers
     * @param token Address of the token pool to claim rewards from
     * @param epoch Epoch to claim rewards from
     */
    function _claimEthFeeFromTokenPool(address token, uint256 epoch) internal {
        TokenPoolInfo storage pool = tokenPools[token][epoch];
        TokenProvider storage provider = tokenProviders[token][msg.sender][
            epoch
        ];
        require(
            provider.lpShares > 0 || provider.pendingReward > 0,
            "No liquidity or rewards"
        );

        uint256 accumulated = (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        uint256 reward = accumulated -
            provider.rewardDebt +
            provider.pendingReward;
        require(reward > 0, "No rewards");

        provider.rewardDebt = accumulated;
        provider.pendingReward = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "ETH transfer failed");

        emit EthFeeClaimedFromTokenPool(msg.sender, reward, token, epoch);
    }

    /**
     * @notice Calculate withdrawal amount with proper validation
     * @param sharesToBurn Number of shares being burned
     * @param totalAmount Total amount in pool
     * @param totalShares Total shares in pool
     * @return withdrawalAmount Amount to withdraw
     */
    function _calculateWithdrawalAmount(
        uint256 sharesToBurn,
        uint256 totalAmount,
        uint256 totalShares
    ) internal pure returns (uint256 withdrawalAmount) {
        require(sharesToBurn > 0, "Shares to burn must be greater than 0");
        require(totalShares > 0, "Total shares must be greater than 0");

        // Calculate withdrawal amount proportionally
        withdrawalAmount = (sharesToBurn * totalAmount) / totalShares;

        require(
            withdrawalAmount <= totalAmount,
            "Withdrawal amount exceeds pool balance"
        );

        return withdrawalAmount;
    }

    /**
     * @notice Gets ETH pool information for a specific token
     * @param token Address of the token to get ETH pool info for
     * @param epoch Epoch to get ETH pool info for
     * @return ETHPoolInfo struct containing ETH pool details
     */
    function getETHPoolInfo(
        address token,
        uint256 epoch
    ) external view returns (ETHPoolInfo memory) {
        return ethPools[token][epoch];
    }

    /**
     * @notice Gets token pool information for a specific token
     * @param token Address of the token to get token pool info for
     * @param epoch Epoch to get token pool info for
     * @return TokenPoolInfo struct containing token pool details
     */
    function getTokenPoolInfo(
        address token,
        uint256 epoch
    ) external view returns (TokenPoolInfo memory) {
        return tokenPools[token][epoch];
    }

    /**
     * @notice Gets a user's LP shares for token pool
     * @param token Address of the token
     * @param user Address of the user
     * @param epoch Epoch to get token provider LP shares for
     * @return lpShares User's LP shares in token pool
     */
    function getTokenProviderLPShares(
        address token,
        address user,
        uint256 epoch
    ) external view returns (uint256 lpShares) {
        return tokenProviders[token][user][epoch].lpShares;
    }

    /**
     * @notice Sets the gradient registry address
     * @param _gradientRegistry New gradient registry address
     * @dev Only callable by the contract owner
     */
    function setRegistry(
        IGradientRegistry _gradientRegistry
    ) external onlyOwner {
        require(
            address(_gradientRegistry) != address(0),
            "Invalid gradient registry"
        );
        emit RegistryUpdated(
            address(gradientRegistry),
            address(_gradientRegistry)
        );
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Set minimum ETH liquidity requirement
     * @param _minLiquidity New minimum ETH liquidity amount
     * @dev Only callable by the contract owner
     */
    function setMinLiquidity(uint256 _minLiquidity) external onlyOwner {
        require(_minLiquidity > 0, "Minimum liquidity must be greater than 0");
        minLiquidity = _minLiquidity;
        emit MinLiquidityUpdated(_minLiquidity);
    }

    /**
     * @notice Set minimum token liquidity requirement
     * @param _minTokenLiquidity New minimum token liquidity amount
     * @dev Only callable by the contract owner
     */
    function setMinTokenLiquidity(
        uint256 _minTokenLiquidity
    ) external onlyOwner {
        require(
            _minTokenLiquidity > 0,
            "Minimum token liquidity must be greater than 0"
        );
        minTokenLiquidity = _minTokenLiquidity;
        emit MinTokenLiquidityUpdated(_minTokenLiquidity);
    }

    /**
     * @notice Get the Uniswap V2 pair address for a given token
     * @param token Address of the token
     * @return pairAddress Address of the Uniswap V2 pair
     */
    function getPairAddress(
        address token
    ) public view returns (address pairAddress) {
        address routerAddress = gradientRegistry.router();
        require(routerAddress != address(0), "Router not set");

        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address factory = router.factory();
        address weth = router.WETH();

        IUniswapV2Factory factoryContract = IUniswapV2Factory(factory);
        return factoryContract.getPair(token, weth);
    }

    /**
     * @notice Get the reserves for a token pair
     * @param token Address of the token
     * @return reserveETH ETH reserve amount
     * @return reserveToken Token reserve amount
     */
    function getReserves(
        address token
    ) public view returns (uint256 reserveETH, uint256 reserveToken) {
        address pairAddress = getPairAddress(token);
        require(pairAddress != address(0), "Pair does not exist");

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pairAddress)
            .getReserves();
        address token0 = IUniswapV2Pair(pairAddress).token0();

        (reserveETH, reserveToken) = token0 == token
            ? (reserve1, reserve0)
            : (reserve0, reserve1);
    }

    /**
     * @notice Withdraw excessive funds that exceed LP contributions
     * @param token Address of the token to withdraw excessive funds for
     * @dev Only callable by contract owner
     */
    function withdrawExcessiveFunds(
        address token
    ) external onlyOwner nonReentrant {
        require(token != address(0), "Invalid token address");

        // Calculate excessive ETH (overall contract balance)
        uint256 currentEthBalance = address(this).balance;
        uint256 totalEthContributed = totalEthAdded - totalEthRemoved;
        uint256 excessiveEth = 0;

        if (currentEthBalance > totalEthContributed) {
            excessiveEth = currentEthBalance - totalEthContributed;
        }

        // Calculate excessive tokens (overall contract balance)
        uint256 currentTokenBalance = IERC20(token).balanceOf(address(this));
        uint256 totalTokensContributed = totalTokensAdded[token] -
            totalTokensRemoved[token];
        uint256 excessiveTokens = 0;

        if (currentTokenBalance > totalTokensContributed) {
            excessiveTokens = currentTokenBalance - totalTokensContributed;
        }

        require(
            excessiveEth > 0 || excessiveTokens > 0,
            "No excessive funds to withdraw"
        );

        // Withdraw excessive ETH
        if (excessiveEth > 0) {
            (bool success, ) = owner().call{value: excessiveEth}("");
            require(success, "ETH withdrawal failed");

            emit ExcessiveFundsWithdrawn(
                owner(),
                address(0),
                excessiveEth,
                "Excessive ETH"
            );
        }

        // Withdraw excessive tokens
        if (excessiveTokens > 0) {
            IERC20(token).safeTransfer(owner(), excessiveTokens);

            emit ExcessiveFundsWithdrawn(
                owner(),
                token,
                excessiveTokens,
                "Excessive tokens"
            );
        }
    }

    /**
     * @notice Get excessive funds information for a token
     * @param token Address of the token
     * @return excessiveEth Amount of excessive ETH
     * @return excessiveTokens Amount of excessive tokens
     */
    function getExcessiveFunds(
        address token
    ) external view returns (uint256 excessiveEth, uint256 excessiveTokens) {
        require(token != address(0), "Invalid token address");

        // Calculate excessive ETH (overall contract balance)
        uint256 currentEthBalance = address(this).balance;
        uint256 totalEthContributed = totalEthAdded - totalEthRemoved;

        if (currentEthBalance > totalEthContributed) {
            excessiveEth = currentEthBalance - totalEthContributed;
        }

        // Calculate excessive tokens (overall contract balance)
        uint256 currentTokenBalance = IERC20(token).balanceOf(address(this));
        uint256 totalTokensContributed = totalTokensAdded[token] -
            totalTokensRemoved[token];

        if (currentTokenBalance > totalTokensContributed) {
            excessiveTokens = currentTokenBalance - totalTokensContributed;
        }
    }

    /**
     * @notice Check if ETH pool is empty and increment ETH epoch if needed
     * @param token Address of the token
     */
    function _checkAndIncrementETHEpoch(address token) internal {
        ETHPoolInfo storage ethPool = ethPools[token][currentETHEpochs[token]];

        // Only increment ETH epoch if ETH pool is empty
        if (ethPool.totalETH == 0) {
            currentETHEpochs[token]++;
            emit EpochIncremented(token, currentETHEpochs[token]);
        }
    }

    /**
     * @notice Check if token pool is empty and increment token epoch if needed
     * @param token Address of the token
     */
    function _checkAndIncrementTokenEpoch(address token) internal {
        TokenPoolInfo storage tokenPool = tokenPools[token][
            currentTokenEpochs[token]
        ];

        // Only increment token epoch if token pool is empty
        if (tokenPool.totalTokens == 0) {
            currentTokenEpochs[token]++;
            emit EpochIncremented(token, currentTokenEpochs[token]);
        }
    }

    /**
     * @notice Get current ETH epoch for a token
     * @param token Address of the token
     * @return Current ETH epoch number
     */
    function getCurrentETHEpoch(address token) external view returns (uint256) {
        return currentETHEpochs[token];
    }

    /**
     * @notice Get current token epoch for a token
     * @param token Address of the token
     * @return Current token epoch number
     */
    function getCurrentTokenEpoch(
        address token
    ) external view returns (uint256) {
        return currentTokenEpochs[token];
    }

    /**
     * @notice Add user to participated epochs if not already present
     * @param token Address of the token
     * @param user Address of the user
     * @param epochId Epoch ID to add
     * @param isETHEpoch Whether this is an ETH epoch (true) or token epoch (false)
     */
    function _addUserToParticipatedEpochs(
        address token,
        address user,
        uint256 epochId,
        bool isETHEpoch
    ) internal {
        uint256[] storage epochs = isETHEpoch
            ? userParticipatedETHEpochs[token][user]
            : userParticipatedTokenEpochs[token][user];
        bool found = false;

        for (uint256 i = 0; i < epochs.length; i++) {
            if (epochs[i] == epochId) {
                found = true;
                break;
            }
        }

        if (!found) {
            epochs.push(epochId);
        }
    }

    function getUserParticipatedETHEpochs(
        address token,
        address user
    ) public view returns (uint256[] memory) {
        return userParticipatedETHEpochs[token][user];
    }

    function getUserParticipatedTokenEpochs(
        address token,
        address user
    ) public view returns (uint256[] memory) {
        return userParticipatedTokenEpochs[token][user];
    }
}

contracts/GradientMarketMakerPoolLatest..content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IGradientRegistry} from "./interfaces/IGradientRegistry.sol";
import {IGradientMarketMakerPoolLatest} from "./interfaces/IGradientMarketMakerPoolLatest.sol";
import {IUniswapV2Pair} from "./interfaces/IUniswapV2Pair.sol";
import {IUniswapV2Router02} from "./interfaces/IUniswapV2Router.sol";
import {IUniswapV2Factory} from "./interfaces/IUniswapV2Factory.sol";

contract GradientMarketMakerPoolLatest is
    Ownable,
    ReentrancyGuard,
    IGradientMarketMakerPoolLatest
{
    using SafeERC20 for IERC20;

    IGradientRegistry public gradientRegistry;

    // Separate pools for ETH and Token providers
    mapping(address => ETHPoolInfo) public ethPools; // token => ETHPoolInfo
    mapping(address => TokenPoolInfo) public tokenPools; // token => TokenPoolInfo

    // User positions in each pool
    mapping(address => mapping(address => ETHProvider)) public ethProviders; // token => user => info
    mapping(address => mapping(address => TokenProvider)) public tokenProviders; // token => user => info

    uint256 public constant SCALE = 1e18;

    // Configurable minimum liquidity requirements
    uint256 public minLiquidity = 1e15; // 0.001 ETH minimum (default)
    uint256 public minTokenLiquidity = 1e15; // 0.001 tokens minimum (default)

    // Track overall totals across all pools
    uint256 public totalEthAdded; // Total ETH added across all pools
    uint256 public totalEthRemoved; // Total ETH removed across all pools

    mapping(address => uint256) public totalTokensAdded; // Total tokens added across all pools (per token)
    mapping(address => uint256) public totalTokensRemoved; // Total tokens removed across all pools (per token)

    modifier isNotBlocked(address token) {
        require(!gradientRegistry.blockedTokens(token), "Token is blocked");
        _;
    }

    modifier onlyRewardDistributor() {
        require(
            gradientRegistry.isRewardDistributor(msg.sender),
            "Only reward distributor can call this function"
        );
        _;
    }

    modifier onlyOrderbook() {
        require(
            msg.sender == gradientRegistry.orderbook(),
            "Only orderbook can call this function"
        );
        _;
    }

    constructor(IGradientRegistry _gradientRegistry) Ownable(msg.sender) {
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Receive ETH for reward distribution
     */
    receive() external payable {}

    /**
     * @notice Calculate LP shares using a more secure formula to prevent precision loss
     * @param amount Amount being deposited
     * @param totalAmount Total amount in pool
     * @param totalShares Total shares in pool
     * @return sharesToMint Number of shares to mint
     */
    function _calculateLPShares(
        uint256 amount,
        uint256 totalAmount,
        uint256 totalShares
    ) internal pure returns (uint256 sharesToMint) {
        require(amount > 0, "Amount must be greater than 0");

        if (totalShares == 0) {
            // First liquidity provider gets shares equal to their contribution
            return amount;
        }

        // Calculate shares proportionally
        sharesToMint = (amount * totalShares) / totalAmount;

        // Ensure minimum share requirement to prevent dust attacks
        require(sharesToMint > 0, "Insufficient shares to mint");

        return sharesToMint;
    }

    /**
     * @notice Updates ETH pool rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateETHPool(address token, uint256 ethAmount) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        ETHPoolInfo storage pool = ethPools[token];

        if (pool.totalLPShares == 0) return;

        uint256 newAccRewardPerShare = pool.accRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccRewardPerShare >= pool.accRewardPerShare,
            "Overflow in reward calculation"
        );

        pool.accRewardPerShare = newAccRewardPerShare;
        pool.rewardBalance += ethAmount;
    }

    /**
     * @notice Updates Token pool rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateTokenPool(address token, uint256 ethAmount) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        TokenPoolInfo storage pool = tokenPools[token];

        if (pool.totalLPShares == 0) return;

        uint256 newAccRewardPerShare = pool.accRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccRewardPerShare >= pool.accRewardPerShare,
            "Overflow in reward calculation"
        );

        pool.accRewardPerShare = newAccRewardPerShare;
        pool.rewardBalance += ethAmount;
    }

    /**
     * @notice Updates ETH pool token rewards before modifying state
     * @param token Address of the token for the pool
     * @param tokenAmount Amount of tokens to distribute as rewards
     */
    function _updateETHPoolTokenRewards(
        address token,
        uint256 tokenAmount
    ) internal {
        require(tokenAmount > 0, "Token amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        ETHPoolInfo storage pool = ethPools[token];

        if (pool.totalLPShares == 0) return;

        uint256 newAccTokenRewardPerShare = pool.accTokenRewardPerShare +
            ((tokenAmount * SCALE) / pool.totalLPShares);
        require(
            newAccTokenRewardPerShare >= pool.accTokenRewardPerShare,
            "Overflow in token reward calculation"
        );

        pool.accTokenRewardPerShare = newAccTokenRewardPerShare;
        pool.tokenRewardBalance += tokenAmount;
    }

    /**
     * @notice Updates Token pool ETH rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updateTokenPoolETHRewards(
        address token,
        uint256 ethAmount
    ) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        TokenPoolInfo storage pool = tokenPools[token];

        if (pool.totalLPShares == 0) return;

        uint256 newAccETHRewardPerShare = pool.accETHRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccETHRewardPerShare >= pool.accETHRewardPerShare,
            "Overflow in ETH reward calculation"
        );

        pool.accETHRewardPerShare = newAccETHRewardPerShare;
        pool.ethRewardBalance += ethAmount;
    }

    /**
     * @notice Add liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addLiquidity(
        address token,
        uint256 tokenAmount
    ) external payable isNotBlocked(token) nonReentrant {
        require(msg.value >= minLiquidity, "ETH amount below minimum");
        require(tokenAmount >= minTokenLiquidity, "Token amount below minimum");
        require(token != address(0), "Invalid token address");

        _addETHLiquidity(token, msg.value);
        _addTokenLiquidity(token, tokenAmount);
    }

    /**
     * @notice Add ETH liquidity to the pool
     * @param token Address of the token to provide ETH liquidity for
     * @dev Requires ETH to be sent with the transaction
     */
    function addETHLiquidity(
        address token
    ) public payable isNotBlocked(token) nonReentrant {
        require(msg.value >= minLiquidity, "ETH amount below minimum");
        require(token != address(0), "Invalid token address");

        _addETHLiquidity(token, msg.value);
    }

    /**
     * @notice Add ETH liquidity to the pool
     * @param token Address of the token to provide ETH liquidity for
     * @param ethAmount Amount of ETH to deposit
     */
    function _addETHLiquidity(address token, uint256 ethAmount) internal {
        ETHPoolInfo storage pool = ethPools[token];

        if (pool.uniswapPair == address(0)) {
            pool.uniswapPair = getPairAddress(token);
        }
        require(pool.uniswapPair != address(0), "Pair does not exist");

        ETHProvider storage provider = ethProviders[token][msg.sender];

        // Calculate pending ETH rewards before update
        if (provider.lpShares > 0) {
            uint256 pendingEth = (provider.lpShares * pool.accRewardPerShare) /
                SCALE -
                provider.rewardDebt;
            provider.pendingReward += pendingEth;

            // Calculate pending token rewards before update
            uint256 pendingTokens = (provider.lpShares *
                pool.accTokenRewardPerShare) /
                SCALE -
                provider.tokenRewardDebt;
            provider.pendingTokenReward += pendingTokens;
        }

        // Calculate LP shares to mint
        uint256 lpSharesToMint = _calculateLPShares(
            ethAmount,
            pool.accountedEth,
            pool.totalLPShares
        );

        provider.lpShares += lpSharesToMint;
        provider.ethAmount += ethAmount;
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.tokenRewardDebt =
            (provider.lpShares * pool.accTokenRewardPerShare) /
            SCALE;

        pool.totalETH += ethAmount;
        pool.accountedEth += ethAmount;
        pool.totalLPShares += lpSharesToMint;

        // Track total ETH added by LPs
        totalEthAdded += ethAmount;

        emit ETHLiquidityDeposited(
            msg.sender,
            token,
            ethAmount,
            lpSharesToMint
        );
    }

    /**
     * @notice Add token liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function addTokenLiquidity(
        address token,
        uint256 tokenAmount
    ) public isNotBlocked(token) nonReentrant {
        require(tokenAmount >= minTokenLiquidity, "Token amount below minimum");
        require(token != address(0), "Invalid token address");

        _addTokenLiquidity(token, tokenAmount);
    }

    /**
     * @notice Add token liquidity to the pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     */
    function _addTokenLiquidity(address token, uint256 tokenAmount) internal {
        TokenPoolInfo storage pool = tokenPools[token];

        if (pool.uniswapPair == address(0)) {
            pool.uniswapPair = getPairAddress(token);
        }
        require(pool.uniswapPair != address(0), "Pair does not exist");

        TokenProvider storage provider = tokenProviders[token][msg.sender];

        // Calculate pending token rewards before update
        if (provider.lpShares > 0) {
            uint256 pendingTokens = (provider.lpShares *
                pool.accRewardPerShare) /
                SCALE -
                provider.rewardDebt;
            provider.pendingReward += pendingTokens;

            // Calculate pending ETH rewards before update
            uint256 pendingEth = (provider.lpShares *
                pool.accETHRewardPerShare) /
                SCALE -
                provider.ethRewardDebt;
            provider.pendingETHReward += pendingEth;
        }

        // Calculate LP shares to mint
        uint256 lpSharesToMint = _calculateLPShares(
            tokenAmount,
            pool.accountedToken,
            pool.totalLPShares
        );

        provider.lpShares += lpSharesToMint;
        provider.tokenAmount += tokenAmount;
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.ethRewardDebt =
            (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE;

        pool.totalTokens += tokenAmount;
        pool.accountedToken += tokenAmount;
        pool.totalLPShares += lpSharesToMint;

        // Track total tokens added by LPs
        totalTokensAdded[token] += tokenAmount;

        // Transfer tokens from user
        IERC20(token).safeTransferFrom(msg.sender, address(this), tokenAmount);

        emit TokenLiquidityDeposited(
            msg.sender,
            token,
            tokenAmount,
            lpSharesToMint
        );
    }

    /**
     * @notice Remove liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     * @param minTokenAmount Minimum amount of tokens to receive
     */
    function removeLiquidity(
        address token,
        uint256 shares,
        uint256 minEthAmount,
        uint256 minTokenAmount
    ) external isNotBlocked(token) nonReentrant {
        require(shares > 0 && shares <= 10000, "Invalid shares percentage");
        require(token != address(0), "Invalid token address");

        _removeETHLiquidity(token, shares, minEthAmount);
        _removeTokenLiquidity(token, shares, minTokenAmount);
    }

    /**
     * @notice Remove ETH liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     */
    function removeETHLiquidity(
        address token,
        uint256 shares,
        uint256 minEthAmount
    ) external isNotBlocked(token) nonReentrant {
        require(shares > 0 && shares <= 10000, "Invalid shares percentage");
        require(token != address(0), "Invalid token address");
        _removeETHLiquidity(token, shares, minEthAmount);
    }

    /**
     * @notice Remove ETH liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minEthAmount Minimum amount of ETH to receive
     */
    function _removeETHLiquidity(
        address token,
        uint256 shares,
        uint256 minEthAmount
    ) internal {
        ETHPoolInfo storage pool = ethPools[token];
        ETHProvider storage provider = ethProviders[token][msg.sender];

        require(pool.totalLPShares > 0, "No ETH liquidity in pool");
        require(provider.ethAmount > 0, "No ETH liquidity to withdraw");

        // Calculate pending ETH rewards before withdrawing
        uint256 pendingEth = (provider.lpShares * pool.accRewardPerShare) /
            SCALE -
            provider.rewardDebt;
        provider.pendingReward += pendingEth;

        // Calculate pending token rewards before withdrawing
        uint256 pendingTokens = (provider.lpShares *
            pool.accTokenRewardPerShare) /
            SCALE -
            provider.tokenRewardDebt;
        provider.pendingTokenReward += pendingTokens;

        // Calculate LP shares to burn based on withdrawal percentage
        uint256 lpSharesToBurn = (provider.lpShares * shares) / 10000;
        require(lpSharesToBurn > 0, "No shares to burn");
        require(
            lpSharesToBurn <= provider.lpShares,
            "Insufficient shares to burn"
        );

        // Calculate actual withdrawal amounts based on LP shares
        uint256 actualEthWithdraw = _calculateWithdrawalAmount(
            lpSharesToBurn,
            pool.totalETH,
            pool.totalLPShares
        );
        require(actualEthWithdraw <= pool.totalETH, "Insufficient ETH in pool");

        // Update balances
        provider.ethAmount -= actualEthWithdraw;
        provider.lpShares -= lpSharesToBurn;

        // Calculate accounted values BEFORE reducing totalLPShares
        uint256 accountedEthToRemove = (pool.accountedEth * lpSharesToBurn) /
            pool.totalLPShares;

        pool.totalETH -= actualEthWithdraw;
        pool.totalLPShares -= lpSharesToBurn;
        pool.accountedEth -= accountedEthToRemove;

        // Update reward debt for remaining shares
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.tokenRewardDebt =
            (provider.lpShares * pool.accTokenRewardPerShare) /
            SCALE;

        // Transfer ETH back to user
        require(
            actualEthWithdraw >= minEthAmount,
            "Insufficient ETH withdrawn"
        );
        (bool success, ) = payable(msg.sender).call{value: actualEthWithdraw}(
            ""
        );
        require(success, "ETH transfer failed");

        // Transfer accumulated token rewards to user
        if (provider.pendingTokenReward > 0) {
            uint256 tokenRewards = provider.pendingTokenReward;
            provider.pendingTokenReward = 0;
            IERC20(token).safeTransfer(msg.sender, tokenRewards);

            emit PoolSharesClaimed(msg.sender, tokenRewards, token, false);
        }

        // Track total ETH removed by LPs
        totalEthRemoved += actualEthWithdraw;

        emit ETHLiquidityWithdrawn(
            msg.sender,
            token,
            actualEthWithdraw,
            lpSharesToBurn
        );
    }

    /**
     * @notice Remove token liquidity from the pool
     * @param token Address of the token to withdraw from
     * @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
     * @param minTokenAmount Minimum amount of tokens to receive
     */
    function removeTokenLiquidity(
        address token,
        uint256 shares,
        uint256 minTokenAmount
    ) external isNotBlocked(token) nonReentrant {
        require(shares > 0 && shares <= 10000, "Invalid shares percentage");
        require(token != address(0), "Invalid token address");

        _removeTokenLiquidity(token, shares, minTokenAmount);
    }

    function _removeTokenLiquidity(
        address token,
        uint256 shares,
        uint256 minTokenAmount
    ) internal {
        TokenPoolInfo storage pool = tokenPools[token];
        TokenProvider storage provider = tokenProviders[token][msg.sender];

        require(pool.totalLPShares > 0, "No token liquidity in pool");
        require(provider.tokenAmount > 0, "No token liquidity to withdraw");

        // Calculate pending token rewards before withdrawing
        uint256 pendingTokens = (provider.lpShares * pool.accRewardPerShare) /
            SCALE -
            provider.rewardDebt;
        provider.pendingReward += pendingTokens;

        // Calculate pending ETH rewards before withdrawing
        uint256 pendingEth = (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE -
            provider.ethRewardDebt;
        provider.pendingETHReward += pendingEth;

        uint256 lpSharesToBurn;

        lpSharesToBurn = (provider.lpShares * shares) / 10000;
        require(lpSharesToBurn > 0, "No shares to burn");
        require(
            lpSharesToBurn <= provider.lpShares,
            "Insufficient shares to burn"
        );

        // Calculate actual withdrawal amounts based on LP shares
        uint256 actualTokenWithdraw = _calculateWithdrawalAmount(
            lpSharesToBurn,
            pool.totalTokens,
            pool.totalLPShares
        );
        require(
            actualTokenWithdraw <= pool.totalTokens,
            "Insufficient tokens in pool"
        );

        // Update balances
        provider.tokenAmount -= actualTokenWithdraw;
        provider.lpShares -= lpSharesToBurn;

        // Calculate accounted values BEFORE reducing totalLPShares
        uint256 accountedTokenToRemove = (pool.accountedToken *
            lpSharesToBurn) / pool.totalLPShares;

        pool.totalTokens -= actualTokenWithdraw;
        pool.totalLPShares -= lpSharesToBurn;
        pool.accountedToken -= accountedTokenToRemove;

        // Update reward debt for remaining shares
        provider.rewardDebt =
            (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        provider.ethRewardDebt =
            (provider.lpShares * pool.accETHRewardPerShare) /
            SCALE;

        // Transfer tokens back to user
        require(
            actualTokenWithdraw >= minTokenAmount,
            "Insufficient token withdrawn"
        );
        IERC20(token).safeTransfer(msg.sender, actualTokenWithdraw);

        // Transfer accumulated ETH rewards to user
        if (provider.pendingETHReward > 0) {
            uint256 ethRewards = provider.pendingETHReward;
            provider.pendingETHReward = 0;
            (bool success, ) = payable(msg.sender).call{value: ethRewards}("");
            require(success, "ETH reward transfer failed");

            emit PoolSharesClaimed(msg.sender, ethRewards, token, true);
        }

        // Track total tokens removed by LPs
        totalTokensRemoved[token] += actualTokenWithdraw;

        emit TokenLiquidityWithdrawn(
            msg.sender,
            token,
            actualTokenWithdraw,
            lpSharesToBurn
        );
    }

    /**
     * @notice Execute buy order - Orderbook sends ETH, receives tokens
     * @param token The token being bought
     * @param ethAmount Amount of ETH sent by orderbook
     * @param tokenAmount Amount of tokens to send to orderbook
     * @dev Only callable by the orderbook contract
     */
    function executeBuyOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external payable isNotBlocked(token) onlyOrderbook {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(tokenAmount > 0, "Token amount must be greater than 0");
        require(msg.value == ethAmount, "ETH amount mismatch");

        TokenPoolInfo storage tokenPool = tokenPools[token];
        require(
            tokenPool.totalTokens >= tokenAmount,
            "Insufficient token liquidity"
        );

        // Token pool provides tokens to orderbook
        tokenPool.totalTokens -= tokenAmount;
        totalTokensRemoved[token] += tokenAmount;
        // Token pool receives ETH rewards for providing tokens
        _updateTokenPoolETHRewards(token, ethAmount);

        // Transfer tokens to orderbook
        IERC20(token).safeTransfer(msg.sender, tokenAmount);

        emit PoolBalanceUpdated(
            token,
            ethPools[token].totalETH,
            tokenPool.totalTokens,
            ethPools[token].totalLPShares,
            tokenPool.totalLPShares
        );
    }

    /**
     * @notice Execute sell order - Orderbook sends tokens, receives ETH
     * @param token The token being sold
     * @param ethAmount Amount of ETH to send to orderbook
     * @param tokenAmount Amount of tokens sent by orderbook
     * @dev Only callable by the orderbook contract
     */
    function executeSellOrder(
        address token,
        uint256 ethAmount,
        uint256 tokenAmount
    ) external isNotBlocked(token) onlyOrderbook {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(tokenAmount > 0, "Token amount must be greater than 0");

        ETHPoolInfo storage ethPool = ethPools[token];
        require(ethPool.totalETH >= ethAmount, "Insufficient ETH liquidity");

        // Transfer tokens from orderbook to market maker pool
        IERC20(token).safeTransferFrom(msg.sender, address(this), tokenAmount);

        // ETH pool provides ETH to orderbook
        ethPool.totalETH -= ethAmount;
        totalEthRemoved += ethAmount;

        // ETH pool receives token rewards for providing ETH
        _updateETHPoolTokenRewards(token, tokenAmount);

        // Transfer ETH to orderbook
        (bool success, ) = payable(msg.sender).call{value: ethAmount}("");
        require(success, "ETH transfer to orderbook failed");

        emit PoolBalanceUpdated(
            token,
            ethPool.totalETH,
            tokenPools[token].totalTokens,
            ethPool.totalLPShares,
            tokenPools[token].totalLPShares
        );
    }

    /// @notice Distributes fee distribution from orderbook to be distributed to market makers
    /// @param token Address of the token pool to distribute fees for
    /// @param isETHPool Whether to distribute to ETH pool (true) or token pool (false)
    function distributePoolFee(
        address token,
        bool isETHPool
    ) external payable onlyRewardDistributor {
        require(msg.value > 0, "No ETH sent");

        if (isETHPool) {
            ETHPoolInfo storage pool = ethPools[token];
            require(pool.totalLPShares > 0, "No ETH liquidity");
            _updateETHPool(token, msg.value);
        } else {
            TokenPoolInfo storage pool = tokenPools[token];
            require(pool.totalLPShares > 0, "No token liquidity");
            _updateTokenPool(token, msg.value);
        }

        emit PoolFeeDistributed(msg.sender, msg.value, token, isETHPool);
    }

    /// @notice Claim ETH rewards for ETH providers
    /// @param token Address of the token pool to claim rewards from
    function claimEthPoolFee(address token) external nonReentrant {
        ETHPoolInfo storage pool = ethPools[token];
        ETHProvider storage provider = ethProviders[token][msg.sender];
        require(
            provider.lpShares > 0 || provider.pendingReward > 0,
            "No liquidity or rewards"
        );

        uint256 accumulated = (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        uint256 reward = accumulated -
            provider.rewardDebt +
            provider.pendingReward;
        require(reward > 0, "No rewards");

        provider.rewardDebt = accumulated;
        provider.pendingReward = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "ETH transfer failed");

        emit PoolFeeClaimed(msg.sender, reward, token, false);
    }

    /// @notice Claim token rewards for token providers
    /// @param token Address of the token pool to claim rewards from
    function claimTokenPoolFee(address token) external nonReentrant {
        TokenPoolInfo storage pool = tokenPools[token];
        TokenProvider storage provider = tokenProviders[token][msg.sender];
        require(
            provider.lpShares > 0 || provider.pendingReward > 0,
            "No liquidity or rewards"
        );

        uint256 accumulated = (provider.lpShares * pool.accRewardPerShare) /
            SCALE;
        uint256 reward = accumulated -
            provider.rewardDebt +
            provider.pendingReward;
        require(reward > 0, "No rewards");

        provider.rewardDebt = accumulated;
        provider.pendingReward = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "ETH transfer failed");

        emit PoolFeeClaimed(msg.sender, reward, token, false);
    }

    /**
     * @notice Calculate withdrawal amount with proper validation
     * @param sharesToBurn Number of shares being burned
     * @param totalAmount Total amount in pool
     * @param totalShares Total shares in pool
     * @return withdrawalAmount Amount to withdraw
     */
    function _calculateWithdrawalAmount(
        uint256 sharesToBurn,
        uint256 totalAmount,
        uint256 totalShares
    ) internal pure returns (uint256 withdrawalAmount) {
        require(sharesToBurn > 0, "Shares to burn must be greater than 0");
        require(totalShares > 0, "Total shares must be greater than 0");

        // Calculate withdrawal amount proportionally
        withdrawalAmount = (sharesToBurn * totalAmount) / totalShares;

        require(
            withdrawalAmount <= totalAmount,
            "Withdrawal amount exceeds pool balance"
        );

        return withdrawalAmount;
    }

    /**
     * @notice Gets ETH pool information for a specific token
     * @param token Address of the token to get ETH pool info for
     * @return ETHPoolInfo struct containing ETH pool details
     */
    function getETHPoolInfo(
        address token
    ) external view returns (ETHPoolInfo memory) {
        return ethPools[token];
    }

    /**
     * @notice Gets token pool information for a specific token
     * @param token Address of the token to get token pool info for
     * @return TokenPoolInfo struct containing token pool details
     */
    function getTokenPoolInfo(
        address token
    ) external view returns (TokenPoolInfo memory) {
        return tokenPools[token];
    }

    /**
     * @notice Gets a user's current share percentage of the ETH pool
     * @param token Address of the token
     * @param user Address of the user
     * @return sharePercentage User's share percentage in basis points (10000 = 100%)
     */
    function getETHProviderSharePercentage(
        address token,
        address user
    ) internal view returns (uint256 sharePercentage) {
        ETHPoolInfo storage pool = ethPools[token];
        ETHProvider storage provider = ethProviders[token][user];

        if (pool.totalLPShares == 0) {
            return 0;
        }

        return (provider.lpShares * 10000) / pool.totalLPShares;
    }

    /**
     * @notice Gets a user's current share percentage of the token pool
     * @param token Address of the token
     * @param user Address of the user
     * @return sharePercentage User's share percentage in basis points (10000 = 100%)
     */
    function getTokenProviderSharePercentage(
        address token,
        address user
    ) internal view returns (uint256 sharePercentage) {
        TokenPoolInfo storage pool = tokenPools[token];
        TokenProvider storage provider = tokenProviders[token][user];

        if (pool.totalLPShares == 0) {
            return 0;
        }

        return (provider.lpShares * 10000) / pool.totalLPShares;
    }

    /**
     * @notice Gets a user's LP shares for ETH pool
     * @param token Address of the token
     * @param user Address of the user
     * @return lpShares User's LP shares in ETH pool
     */
    function getETHProviderLPShares(
        address token,
        address user
    ) external view returns (uint256 lpShares) {
        return ethProviders[token][user].lpShares;
    }

    /**
     * @notice Gets a user's LP shares for token pool
     * @param token Address of the token
     * @param user Address of the user
     * @return lpShares User's LP shares in token pool
     */
    function getTokenProviderLPShares(
        address token,
        address user
    ) external view returns (uint256 lpShares) {
        return tokenProviders[token][user].lpShares;
    }

    /**
     * @notice Sets the gradient registry address
     * @param _gradientRegistry New gradient registry address
     * @dev Only callable by the contract owner
     */
    function setRegistry(
        IGradientRegistry _gradientRegistry
    ) external onlyOwner {
        require(
            address(_gradientRegistry) != address(0),
            "Invalid gradient registry"
        );
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Set minimum ETH liquidity requirement
     * @param _minLiquidity New minimum ETH liquidity amount
     * @dev Only callable by the contract owner
     */
    function setMinLiquidity(uint256 _minLiquidity) external onlyOwner {
        require(_minLiquidity > 0, "Minimum liquidity must be greater than 0");
        minLiquidity = _minLiquidity;
        emit MinLiquidityUpdated(_minLiquidity);
    }

    /**
     * @notice Set minimum token liquidity requirement
     * @param _minTokenLiquidity New minimum token liquidity amount
     * @dev Only callable by the contract owner
     */
    function setMinTokenLiquidity(
        uint256 _minTokenLiquidity
    ) external onlyOwner {
        require(
            _minTokenLiquidity > 0,
            "Minimum token liquidity must be greater than 0"
        );
        minTokenLiquidity = _minTokenLiquidity;
        emit MinTokenLiquidityUpdated(_minTokenLiquidity);
    }

    /**
     * @notice Get the Uniswap V2 pair address for a given token
     * @param token Address of the token
     * @return pairAddress Address of the Uniswap V2 pair
     */
    function getPairAddress(
        address token
    ) public view returns (address pairAddress) {
        address routerAddress = gradientRegistry.router();
        require(routerAddress != address(0), "Router not set");

        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address factory = router.factory();
        address weth = router.WETH();

        IUniswapV2Factory factoryContract = IUniswapV2Factory(factory);
        return factoryContract.getPair(token, weth);
    }

    /**
     * @notice Get the reserves for a token pair
     * @param token Address of the token
     * @return reserveETH ETH reserve amount
     * @return reserveToken Token reserve amount
     */
    function getReserves(
        address token
    ) public view returns (uint256 reserveETH, uint256 reserveToken) {
        address pairAddress = getPairAddress(token);
        require(pairAddress != address(0), "Pair does not exist");

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pairAddress)
            .getReserves();
        address token0 = IUniswapV2Pair(pairAddress).token0();

        (reserveETH, reserveToken) = token0 == token
            ? (reserve1, reserve0)
            : (reserve0, reserve1);
    }

    // Legacy interface compatibility - these functions now delegate to the new structure
    function getPoolInfo(
        address token
    ) external view returns (PoolInfo memory) {
        ETHPoolInfo storage ethPool = ethPools[token];
        TokenPoolInfo storage tokenPool = tokenPools[token];

        return
            PoolInfo({
                totalEth: ethPool.totalETH,
                totalToken: tokenPool.totalTokens,
                totalLiquidity: ethPool.totalETH + tokenPool.totalTokens,
                totalLPShares: ethPool.totalLPShares + tokenPool.totalLPShares,
                accRewardPerShare: 0, // Not applicable in new structure
                rewardBalance: ethPool.rewardBalance + tokenPool.rewardBalance,
                uniswapPair: ethPool.uniswapPair,
                accountedEth: ethPool.totalETH,
                accountedToken: tokenPool.totalTokens
            });
    }

    function getUserSharePercentage(
        address token,
        address user
    ) external view returns (uint256 sharePercentage) {
        uint256 ethShare = getETHProviderSharePercentage(token, user);
        uint256 tokenShare = getTokenProviderSharePercentage(token, user);
        return ethShare > tokenShare ? ethShare : tokenShare;
    }

    function getUserLPShares(
        address token,
        address user
    ) external view returns (uint256 lpShares) {
        return
            ethProviders[token][user].lpShares +
            tokenProviders[token][user].lpShares;
    }

    /**
     * @notice Withdraw excessive funds that exceed LP contributions
     * @param token Address of the token to withdraw excessive funds for
     * @dev Only callable by contract owner
     */
    function withdrawExcessiveFunds(
        address token
    ) external onlyOwner nonReentrant {
        require(token != address(0), "Invalid token address");

        // Calculate excessive ETH (overall contract balance)
        uint256 currentEthBalance = address(this).balance;
        uint256 totalEthContributed = totalEthAdded - totalEthRemoved;
        uint256 excessiveEth = 0;

        if (currentEthBalance > totalEthContributed) {
            excessiveEth = currentEthBalance - totalEthContributed;
        }

        // Calculate excessive tokens (overall contract balance)
        uint256 currentTokenBalance = IERC20(token).balanceOf(address(this));
        uint256 totalTokensContributed = totalTokensAdded[token] -
            totalTokensRemoved[token];
        uint256 excessiveTokens = 0;

        if (currentTokenBalance > totalTokensContributed) {
            excessiveTokens = currentTokenBalance - totalTokensContributed;
        }

        require(
            excessiveEth > 0 || excessiveTokens > 0,
            "No excessive funds to withdraw"
        );

        // Withdraw excessive ETH
        if (excessiveEth > 0) {
            (bool success, ) = owner().call{value: excessiveEth}("");
            require(success, "ETH withdrawal failed");

            emit ExcessiveFundsWithdrawn(
                owner(),
                address(0),
                excessiveEth,
                "Excessive ETH"
            );
        }

        // Withdraw excessive tokens
        if (excessiveTokens > 0) {
            IERC20(token).safeTransfer(owner(), excessiveTokens);

            emit ExcessiveFundsWithdrawn(
                owner(),
                token,
                excessiveTokens,
                "Excessive tokens"
            );
        }
    }

    /**
     * @notice Get excessive funds information for a token
     * @param token Address of the token
     * @return excessiveEth Amount of excessive ETH
     * @return excessiveTokens Amount of excessive tokens
     */
    function getExcessiveFunds(
        address token
    ) external view returns (uint256 excessiveEth, uint256 excessiveTokens) {
        require(token != address(0), "Invalid token address");

        // Calculate excessive ETH (overall contract balance)
        uint256 currentEthBalance = address(this).balance;
        uint256 totalEthContributed = totalEthAdded - totalEthRemoved;

        if (currentEthBalance > totalEthContributed) {
            excessiveEth = currentEthBalance - totalEthContributed;
        }

        // Calculate excessive tokens (overall contract balance)
        uint256 currentTokenBalance = IERC20(token).balanceOf(address(this));
        uint256 totalTokensContributed = totalTokensAdded[token] -
            totalTokensRemoved[token];

        if (currentTokenBalance > totalTokensContributed) {
            excessiveTokens = currentTokenBalance - totalTokensContributed;
        }
    }
}

contracts/GradientMarketMakerPoolV1.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./interfaces/IGradientRegistry.sol";
import "./interfaces/IGradientMarketMakerPoolV1.sol";
import "./interfaces/IUniswapV2Pair.sol";
import "./interfaces/IUniswapV2Router.sol";
import "./interfaces/IUniswapV2Factory.sol";

contract GradientMarketMakerPoolV1 is
    Ownable,
    ReentrancyGuard,
    IGradientMarketMakerPoolV1
{
    using SafeERC20 for IERC20;

    IGradientRegistry public gradientRegistry;

    mapping(address => PoolInfo) public pools; // token => PoolInfo
    mapping(address => mapping(address => MarketMaker)) public marketMakers; // token => user => info

    uint256 public constant SCALE = 1e18;

    modifier poolExists(address token) {
        address pairAddress = getPairAddress(token);
        require(pairAddress != address(0), "Pair does not exist");
        require(pools[token].uniswapPair != address(0), "Pool not initialized");
        _;
    }

    modifier isNotBlocked(address token) {
        require(!gradientRegistry.blockedTokens(token), "Token is blocked");
        _;
    }

    modifier onlyRewardDistributor() {
        require(
            gradientRegistry.isRewardDistributor(msg.sender),
            "Only reward distributor can call this function"
        );
        _;
    }

    modifier onlyOrderbook() {
        require(
            msg.sender == gradientRegistry.orderbook(),
            "Only orderbook can call this function"
        );
        _;
    }

    constructor(IGradientRegistry _gradientRegistry) Ownable(msg.sender) {
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Receive ETH for reward distribution
     */
    receive() external payable {}

    /**
     * @notice Updates pool rewards before modifying state
     * @param token Address of the token for the pool
     * @param ethAmount Amount of ETH to distribute as rewards
     */
    function _updatePool(address token, uint256 ethAmount) internal {
        require(ethAmount > 0, "ETH amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        PoolInfo storage pool = pools[token];

        if (pool.totalLPShares == 0) return;

        uint256 newAccRewardPerShare = pool.accRewardPerShare +
            ((ethAmount * SCALE) / pool.totalLPShares);
        require(
            newAccRewardPerShare >= pool.accRewardPerShare,
            "Overflow in reward calculation"
        );

        pool.accRewardPerShare = newAccRewardPerShare;
        pool.rewardBalance += ethAmount;
    }

    /**
     * @notice Allows users to provide liquidity to a pool
     * @param token Address of the token to provide liquidity for
     * @param tokenAmount Amount of tokens to deposit
     * @param minTokenAmount Minimum amount of tokens to accept (slippage protection)
     * @dev Requires ETH to be sent with the transaction in the correct ratio
     * @dev Calculates pending rewards before updating user's liquidity
     */
    function provideLiquidity(
        address token,
        uint256 tokenAmount,
        uint256 minTokenAmount
    ) external payable nonReentrant {
        PoolInfo storage pool = pools[token];

        if (pool.uniswapPair == address(0)) {
            pool.uniswapPair = getPairAddress(token);
        }
        require(pool.uniswapPair != address(0), "Pair does not exist");

        // Get reserves from Uniswap pair
        (uint256 reserveETH, uint256 reserveToken) = getReserves(token);
        require(
            reserveETH > 0 && reserveToken > 0,
            "Insufficient liquidity in Uniswap pair"
        );

        uint256 expectedTokens = (msg.value * reserveToken) / reserveETH;

        // Slippage protection - ensure user gets at least minTokenAmount
        require(tokenAmount >= minTokenAmount, "Slippage too high");

        // Allow 1% slippage tolerance for the ratio check
        require(
            tokenAmount >= (expectedTokens * 99) / 100 &&
                tokenAmount <= (expectedTokens * 101) / 100,
            "Invalid liquidity ratio"
        );

        IERC20(token).safeTransferFrom(msg.sender, address(this), tokenAmount);

        MarketMaker storage mm = marketMakers[token][msg.sender];
        uint256 userLiquidity = mm.tokenAmount + mm.ethAmount;

        // Calculate pending reward before update
        if (userLiquidity > 0) {
            uint256 pending = (mm.lpShares * pool.accRewardPerShare) /
                SCALE -
                mm.rewardDebt;
            mm.pendingReward += pending;
        }

        // Calculate LP shares to mint
        uint256 lpSharesToMint;
        uint256 totalContribution = tokenAmount + msg.value;
        uint256 totalAccounted = pool.accountedEth + pool.accountedToken;
        if (pool.totalLPShares == 0) {
            // First liquidity provider gets shares equal to their contribution
            lpSharesToMint = totalContribution;
        } else {
            // Calculate shares based on proportional contribution
            lpSharesToMint =
                (totalContribution * pool.totalLPShares) /
                totalAccounted;
        }

        mm.lpShares += lpSharesToMint;
        mm.ethAmount += msg.value;
        mm.tokenAmount += tokenAmount;
        mm.rewardDebt = (mm.lpShares * pool.accRewardPerShare) / SCALE;

        pool.totalLiquidity += tokenAmount + msg.value;
        pool.totalEth += msg.value;
        pool.totalToken += tokenAmount;

        pool.accountedEth += msg.value;
        pool.accountedToken += tokenAmount;
        pool.totalLPShares += lpSharesToMint;

        emit LiquidityDeposited(
            msg.sender,
            token,
            msg.value,
            tokenAmount,
            lpSharesToMint
        );
    }

    /// @notice Allows market maker to withdraw liquidity and claim pending rewards
    /// @param token Address of the token to withdraw from
    /// @param shares Percentage of pool to withdraw (in basis points, 10000 = 100%)
    function withdrawLiquidity(
        address token,
        uint256 shares
    ) external nonReentrant {
        PoolInfo storage pool = pools[token];
        MarketMaker storage mm = marketMakers[token][msg.sender];

        require(shares > 0 && shares <= 10000, "Invalid shares percentage");
        require(pool.totalLiquidity > 0, "No liquidity in pool");

        uint256 userLiquidity = mm.tokenAmount + mm.ethAmount;
        require(userLiquidity > 0, "No liquidity to withdraw");

        // Calculate pending rewards before withdrawing
        uint256 pending = (mm.lpShares * pool.accRewardPerShare) /
            SCALE -
            mm.rewardDebt;
        mm.pendingReward += pending;

        // Calculate LP shares to burn based on withdrawal percentage
        uint256 lpSharesToBurn = (mm.lpShares * shares) / 10000;
        require(lpSharesToBurn > 0, "No shares to burn");

        // Calculate actual withdrawal amounts based on LP shares
        uint256 actualTokenWithdraw = (pool.totalToken * lpSharesToBurn) /
            pool.totalLPShares;
        uint256 actualEthWithdraw = (pool.totalEth * lpSharesToBurn) /
            pool.totalLPShares;

        // Update balances
        mm.lpShares -= lpSharesToBurn;

        pool.totalLiquidity -= (actualTokenWithdraw + actualEthWithdraw);
        pool.totalToken -= actualTokenWithdraw;
        pool.totalEth -= actualEthWithdraw;

        // Calculate accounted values BEFORE reducing totalLPShares
        uint256 accountedEthToRemove = (pool.accountedEth * lpSharesToBurn) /
            pool.totalLPShares;
        uint256 accountedTokenToRemove = (pool.accountedToken *
            lpSharesToBurn) / pool.totalLPShares;

        pool.totalLPShares -= lpSharesToBurn;
        pool.accountedEth -= accountedEthToRemove;
        pool.accountedToken -= accountedTokenToRemove;

        // Update reward debt for remaining shares
        mm.rewardDebt = (mm.lpShares * pool.accRewardPerShare) / SCALE;

        // Transfer tokens and ETH back to user
        IERC20(token).safeTransfer(msg.sender, actualTokenWithdraw);
        (bool success, ) = payable(msg.sender).call{value: actualEthWithdraw}(
            ""
        );
        require(success, "ETH transfer failed");

        emit LiquidityWithdrawn(
            msg.sender,
            actualTokenWithdraw,
            actualEthWithdraw,
            lpSharesToBurn
        );
    }

    /// @notice Receives fee distribution from orderbook to be distributed to market makers
    /// @param token Address of the token pool to distribute fees for
    function receiveFeeDistribution(
        address token
    ) external payable poolExists(token) onlyRewardDistributor {
        PoolInfo storage pool = pools[token];
        require(pool.totalLiquidity > 0, "No liquidity");
        require(msg.value > 0, "No ETH sent");

        _updatePool(token, msg.value); // pass reward directly
        emit RewardDeposited(token, msg.value);
    }

    /// @notice Claims pending rewards for caller
    /// @param token Address of the token pool to claim rewards from
    function claimReward(address token) external nonReentrant {
        PoolInfo storage pool = pools[token];
        MarketMaker storage mm = marketMakers[token][msg.sender];
        require(
            mm.lpShares > 0 || mm.pendingReward > 0,
            "No liquidity or rewards"
        );

        uint256 accumulated = (mm.lpShares * pool.accRewardPerShare) / SCALE;
        uint256 reward = accumulated - mm.rewardDebt + mm.pendingReward;
        require(reward > 0, "No rewards");

        mm.rewardDebt = accumulated;
        mm.pendingReward = 0;

        (bool success, ) = payable(msg.sender).call{value: reward}("");
        require(success, "ETH transfer failed");

        emit RewardClaimed(msg.sender, reward);
    }

    /**
     * @notice Emergency withdraw function for owner to withdraw all ETH and tokens
     * @param tokens Array of token addresses to withdraw
     * @dev Only callable by contract owner
     * @dev Use this function ONLY in emergency situations such as:
     *      - Contract vulnerability or exploit detected
     *      - Critical bug in liquidity management logic
     *      - Migration to new contract version
     *      - Recovery of stuck or locked funds
     *      - Security incident requiring immediate asset protection
     * @dev This function bypasses all normal withdrawal logic and directly transfers assets
     */
    function emergencyWithdraw(address[] calldata tokens) external onlyOwner {
        // Withdraw all ETH
        uint256 ethBalance = address(this).balance;
        if (ethBalance > 0) {
            (bool success, ) = owner().call{value: ethBalance}("");
            require(success, "ETH withdrawal failed");
        }

        // Withdraw all specified tokens
        for (uint256 i = 0; i < tokens.length; i++) {
            address token = tokens[i];
            if (token != address(0)) {
                uint256 tokenBalance = IERC20(token).balanceOf(address(this));
                if (tokenBalance > 0) {
                    IERC20(token).safeTransfer(owner(), tokenBalance);
                }
            }
        }
    }

    /**
     * @notice Emergency withdraw function for owner to withdraw all ETH
     * @dev Only callable by contract owner
     * @dev Use this function ONLY in emergency situations such as:
     *      - Contract vulnerability or exploit detected
     *      - Critical bug in liquidity management logic
     *      - Migration to new contract version
     *      - Recovery of stuck or locked funds
     *      - Security incident requiring immediate asset protection
     * @dev This function bypasses all normal withdrawal logic and directly transfers ETH
     */
    function emergencyWithdrawETH() external onlyOwner {
        uint256 balance = address(this).balance;
        if (balance > 0) {
            (bool success, ) = owner().call{value: balance}("");
            require(success, "ETH withdrawal failed");
        }
    }

    /**
     * @notice Gets pool information for a specific token
     * @param token Address of the token to get pool info for
     * @return PoolInfo struct containing pool details
     */
    function getPoolInfo(
        address token
    ) external view returns (PoolInfo memory) {
        return pools[token];
    }

    /**
     * @notice Gets a user's current share percentage of the pool
     * @param token Address of the token
     * @param user Address of the user
     * @return sharePercentage User's share percentage in basis points (10000 = 100%)
     */
    function getUserSharePercentage(
        address token,
        address user
    ) external view returns (uint256 sharePercentage) {
        PoolInfo storage pool = pools[token];
        MarketMaker storage mm = marketMakers[token][user];

        if (pool.totalLPShares == 0) {
            return 0;
        }

        return (mm.lpShares * 10000) / pool.totalLPShares;
    }

    /**
     * @notice Gets a user's LP shares for a specific token
     * @param token Address of the token
     * @param user Address of the user
     * @return lpShares User's LP shares
     */
    function getUserLPShares(
        address token,
        address user
    ) external view returns (uint256 lpShares) {
        return marketMakers[token][user].lpShares;
    }

    /**
     * @notice Sets the gradient registry address
     * @param _gradientRegistry New gradient registry address
     * @dev Only callable by the contract owner
     */
    function setRegistry(
        IGradientRegistry _gradientRegistry
    ) external onlyOwner {
        require(
            _gradientRegistry.marketMakerPool() != address(0),
            "Invalid gradient registry"
        );
        gradientRegistry = _gradientRegistry;
    }

    /**
     * @notice Transfer ETH to orderbook for order fulfillment
     * @param token The token being traded
     * @param amount The amount of ETH to transfer
     * @dev Only callable by the orderbook contract
     */
    function transferETHToOrderbook(
        address token,
        uint256 amount
    ) external isNotBlocked(token) poolExists(token) onlyOrderbook {
        require(amount > 0, "Amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        // Update pool information
        PoolInfo storage pool = pools[token];
        require(pool.totalLiquidity > 0, "No liquidity");
        require(pool.totalEth >= amount, "Insufficient pool ETH balance");

        // Update pool balances
        pool.totalEth -= amount;
        pool.totalLiquidity -= amount;

        // Transfer ETH to orderbook
        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "ETH transfer to orderbook failed");

        emit PoolBalanceUpdated(
            token,
            pool.totalEth,
            pool.totalToken,
            pool.totalLiquidity,
            pool.totalLPShares
        );
    }

    /**
     * @notice Transfer tokens to orderbook for order fulfillment
     * @param token The token to transfer
     * @param amount The amount of tokens to transfer
     * @dev Only callable by the orderbook contract
     */
    function transferTokenToOrderbook(
        address token,
        uint256 amount
    ) external isNotBlocked(token) poolExists(token) onlyOrderbook {
        require(amount > 0, "Amount must be greater than 0");
        require(token != address(0), "Invalid token address");
        PoolInfo storage pool = pools[token];
        require(pool.totalLiquidity > 0, "No liquidity");
        require(pool.totalToken >= amount, "Insufficient pool token balance");

        // Update pool balances
        pool.totalToken -= amount;
        pool.totalLiquidity -= amount;

        // Transfer tokens to orderbook
        IERC20(token).safeTransfer(msg.sender, amount);

        emit PoolBalanceUpdated(
            token,
            pool.totalEth,
            pool.totalToken,
            pool.totalLiquidity,
            pool.totalLPShares
        );
    }

    /**
     * @notice Receive ETH deposit from orderbook for order fulfillment
     * @param token The token being traded
     * @param amount The amount of ETH to deposit
     * @dev Only callable by the orderbook contract
     */
    function receiveETHFromOrderbook(
        address token,
        uint256 amount
    ) external payable isNotBlocked(token) poolExists(token) onlyOrderbook {
        require(amount > 0, "Amount must be greater than 0");
        require(msg.value == amount, "ETH amount mismatch");

        // Update pool information
        PoolInfo storage pool = pools[token];
        require(pool.totalLiquidity > 0, "No liquidity");

        // Update pool balances
        pool.totalEth += amount;
        pool.totalLiquidity += amount;

        emit ETHReceivedFromOrderbook(msg.sender, amount, token);
        emit PoolBalanceUpdated(
            token,
            pool.totalEth,
            pool.totalToken,
            pool.totalLiquidity,
            pool.totalLPShares
        );
    }

    /**
     * @notice Receive token deposit from orderbook for order fulfillment
     * @param token The token to deposit
     * @param amount The amount of tokens to deposit
     * @dev Only callable by the orderbook contract
     */
    function receiveTokenFromOrderbook(
        address token,
        uint256 amount
    ) external isNotBlocked(token) poolExists(token) onlyOrderbook {
        require(amount > 0, "Amount must be greater than 0");
        require(token != address(0), "Invalid token address");

        // Update pool information
        PoolInfo storage pool = pools[token];
        require(pool.totalLiquidity > 0, "No liquidity");

        // Transfer tokens from orderbook to pool
        IERC20(token).safeTransferFrom(msg.sender, address(this), amount);

        // Update pool balances
        pool.totalToken += amount;
        pool.totalLiquidity += amount;

        emit TokenReceivedFromOrderbook(msg.sender, token, amount);
        emit PoolBalanceUpdated(
            token,
            pool.totalEth,
            pool.totalToken,
            pool.totalLiquidity,
            pool.totalLPShares
        );
    }

    /**
     * @notice Get the Uniswap V2 pair address for a given token
     * @param token Address of the token
     * @return pairAddress Address of the Uniswap V2 pair
     */
    function getPairAddress(
        address token
    ) public view returns (address pairAddress) {
        address routerAddress = gradientRegistry.router();
        require(routerAddress != address(0), "Router not set");

        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        address factory = router.factory();
        address weth = router.WETH();

        IUniswapV2Factory factoryContract = IUniswapV2Factory(factory);
        return factoryContract.getPair(token, weth);
    }

    /**
     * @notice Get the reserves for a token pair
     * @param token Address of the token
     * @return reserveETH ETH reserve amount
     * @return reserveToken Token reserve amount
     */
    function getReserves(
        address token
    ) public view returns (uint256 reserveETH, uint256 reserveToken) {
        address pairAddress = getPairAddress(token);
        require(pairAddress != address(0), "Pair does not exist");

        (uint112 reserve0, uint112 reserve1, ) = IUniswapV2Pair(pairAddress)
            .getReserves();
        address token0 = IUniswapV2Pair(pairAddress).token0();

        (reserveETH, reserveToken) = token0 == token
            ? (reserve1, reserve0)
            : (reserve0, reserve1);
    }
}

contracts/GradientOrderbook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {IGradientRegistry} from "./interfaces/IGradientRegistry.sol";
import {IGradientMarketMakerPool} from "./interfaces/IGradientMarketMakerPool.sol";
import {IUniswapV2Router02} from "./interfaces/IUniswapV2Router.sol";
import {IFallbackExecutor} from "./interfaces/IFallbackExecutor.sol";
import {IERC20Metadata} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
import {IUniswapV2Factory} from "./interfaces/IUniswapV2Factory.sol";
import {IUniswapV2Pair} from "./interfaces/IUniswapV2Pair.sol";

/**
 * @title GradientOrderbook
 * @author Gradient Protocol
 * @notice A decentralized orderbook for trading ERC20 tokens against ETH
 * @dev This contract implements a traditional orderbook with limit and market orders.
 */
contract GradientOrderbook is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    /// @notice Registry contract for accessing other protocol contracts
    IGradientRegistry public gradientRegistry;

    /// @notice Types of orders that can be placed
    enum OrderType {
        Buy,
        Sell
    }

    /// @notice Types of order execution
    enum OrderExecutionType {
        Limit,
        Market
    }

    /// @notice Possible states of an order
    enum OrderStatus {
        Active,
        Filled,
        Cancelled,
        Expired
    }

    /// @notice Structure containing all information about an order
    /// @dev All amounts use the decimal precision of their respective tokens
    struct Order {
        uint256 orderId; // Unique identifier for the order
        address owner; // Address that created the order
        OrderType orderType; // Whether this is a buy or sell order
        OrderExecutionType executionType; // Whether this is a limit or market order
        address token; // Token being traded
        uint256 amount; // Total amount of tokens to trade
        uint256 price; // For limit orders: exact price, For market orders: max price (buy) or min price (sell)
        uint256 filledAmount; // Amount of tokens that have been filled
        uint256 expirationTime; // Timestamp when the order expires
        OrderStatus status; // Current status of the order
    }

    /// @notice Parameters for matching orders
    struct OrderMatch {
        uint256 buyOrderId; // ID of the buy order
        uint256 sellOrderId; // ID of the sell order
        uint256 fillAmount; // Amount of tokens to exchange
    }

    /// @notice Counter for generating unique order IDs
    uint256 private _orderIdCounter;

    /// @notice Fee percentage charged on trades (in basis points, 1 = 0.01%)
    uint256 public feePercentage;

    /// @notice Maximum fee percentage that can be set (in basis points)
    uint256 public constant MAX_FEE_PERCENTAGE = 500; // 5%

    /// @notice Total fees collected
    uint256 public totalFeesCollected;

    /// @notice Mapping from order ID to Order struct
    mapping(uint256 => Order) public orders;

    /// @notice Mapping from token pair + order type + execution type hash to array of order IDs
    /// @dev Key is keccak256(abi.encodePacked(token, orderType, executionType))
    mapping(bytes32 => uint256) public totalOrderCount;
    mapping(bytes32 => uint256) public headOrder;
    mapping(bytes32 => uint256) public tailOrder;
    struct LinkedOrder {
        uint256 prev;
        uint256 next;
        bool exists;
    }
    mapping(bytes32 => mapping(uint256 => LinkedOrder)) public linkedOrders;

    /// @notice Mapping from order ID to its position in the queue
    /// @dev Used for efficient removal of orders from queues
    mapping(uint256 => uint256) private orderQueuePositions;

    /// @notice Divisor used for fee calculations (10000 = 100%)
    uint256 public constant DIVISOR = 10000;

    uint256 public minOrderSize;
    uint256 public maxOrderSize;
    uint256 public maxOrderTtl;

    /// @notice Percentage of fees distributed to market maker pool (in basis points)
    uint256 public mmFeeDistributionPercentage = 7000; // 70% default

    /// @notice Maximum allowed price deviation from market price (in basis points, 1 = 0.01%)
    uint256 public maxPriceDeviation = 500; // 5% default

    /// @notice Emitted when a new order is created
    event OrderCreated(
        uint256 indexed orderId,
        address indexed owner,
        OrderType orderType,
        OrderExecutionType executionType,
        address token,
        uint256 amount,
        uint256 price,
        uint256 expirationTime,
        uint256 totalCost // Add total cost for better tracking
    );

    /// @notice Emitted when an order is cancelled by its owner
    event OrderCancelled(uint256 indexed orderId);

    /// @notice Emitted when an order expires
    event OrderExpired(uint256 indexed orderId);

    /// @notice Emitted when an order is completely filled
    event OrderFulfilled(uint256 indexed orderId, uint256 amount);

    /// @notice Emitted when an order is partially filled
    event OrderPartiallyFulfilled(
        uint256 indexed orderId,
        uint256 amount,
        uint256 remaining
    );

    /// @notice Emitted when fee percentage is updated
    event FeePercentageUpdated(
        uint256 oldFeePercentage,
        uint256 newFeePercentage
    );

    /// @notice Emitted when fees are withdrawn
    event FeesWithdrawn(address indexed recipient, uint256 amount);

    event OrderSizeLimitsUpdated(uint256 minSize, uint256 maxSize);
    event MaxTTLUpdated(uint256 newMaxTTL);
    event RateLimitUpdated(uint256 newInterval);

    /// @notice Emitted when an order is fulfilled through matching
    event OrderFulfilledByMatching(
        uint256 indexed orderId,
        uint256 indexed matchedOrderId,
        uint256 amount,
        uint256 price
    );

    /// @notice Emitted when an order is fulfilled through market maker
    event OrderFulfilledByMarketMaker(
        uint256 indexed orderId,
        address indexed marketMakerPool,
        uint256 amount,
        uint256 price
    );

    /// @notice Emitted when fees are distributed to market maker pool
    event FeeDistributedToPool(
        address indexed marketMakerPool,
        address indexed token,
        uint256 epoch,
        uint256 amount,
        uint256 totalFee
    );

    /// @notice Emitted when MM fee distribution percentage is updated
    event MMFeeDistributionPercentageUpdated(
        uint256 oldPercentage,
        uint256 newPercentage
    );

    /// @notice Emitted when max price deviation is updated
    event MaxPriceDeviationUpdated(uint256 oldDeviation, uint256 newDeviation);

    // Modifiers
    modifier onlyAuthorizedFulfiller() {
        require(
            gradientRegistry.isAuthorizedFulfiller(msg.sender),
            "Caller is not authorized"
        );
        _;
    }

    modifier orderExists(uint256 orderId) {
        require(orders[orderId].owner != address(0), "Order does not exist");
        _;
    }

    modifier onlyOrderOwner(uint256 orderId) {
        require(orders[orderId].owner == msg.sender, "Not order owner");
        _;
    }

    modifier validToken(address token) {
        require(token != address(0), "Invalid token");
        require(token.code.length > 0, "Not a contract");
        // Check if token is blocked
        require(!gradientRegistry.blockedTokens(token), "Token is blocked");
        _;
    }

    constructor(IGradientRegistry _gradientRegistry) Ownable(msg.sender) {
        gradientRegistry = _gradientRegistry;
        feePercentage = 50; // Default 0.5%

        minOrderSize = 1e6; // Example: 0.000001 ETH
        maxOrderSize = 1000 ether; // Example: 1000 ETH
        maxOrderTtl = 30 days; // Example: 30 days
    }

    receive() external payable {}

    fallback() external payable {}

    /// @notice Internal function to calculate and collect fees
    /// @param amount Amount in ETH to calculate fee from
    /// @return uint256 Fee amount collected
    function _collectFee(uint256 amount) internal returns (uint256) {
        uint256 feeAmount = (amount * feePercentage) / DIVISOR;
        totalFeesCollected += feeAmount;
        return feeAmount;
    }

    /// @notice Adds an order to its appropriate queue
    /// @param orderId The ID of the order to add
    /// @param token The token address
    /// @param orderType The type of order (Buy/Sell)
    /// @param executionType The type of execution (Limit/Market)
    function _addOrderToQueue(
        uint256 orderId,
        address token,
        OrderType orderType,
        OrderExecutionType executionType
    ) internal {
        bytes32 queueKey = _getQueueKey(token, orderType, executionType);

        // new Queue system
        linkedOrders[queueKey][orderId] = LinkedOrder({
            prev: tailOrder[queueKey],
            next: 0,
            exists: true
        });

        if (tailOrder[queueKey] != 0) {
            linkedOrders[queueKey][tailOrder[queueKey]].next = orderId;
        } else {
            headOrder[queueKey] = orderId; // First order
        }

        tailOrder[queueKey] = orderId;

        // Store the position of the order in the queue
        orderQueuePositions[orderId] = totalOrderCount[queueKey];
        totalOrderCount[queueKey] += 1;
    }

    function _removeOrderFromLinkedQueue(
        bytes32 queueKey,
        uint256 orderId
    ) internal {
        LinkedOrder storage node = linkedOrders[queueKey][orderId];
        require(node.exists, "Order not in queue");

        if (node.prev != 0) {
            linkedOrders[queueKey][node.prev].next = node.next;
        } else {
            headOrder[queueKey] = node.next; // Head being removed
        }

        if (node.next != 0) {
            linkedOrders[queueKey][node.next].prev = node.prev;
        } else {
            tailOrder[queueKey] = node.prev; // Tail being removed
        }

        delete linkedOrders[queueKey][orderId];
    }

    /// @notice Creates a new order in the orderbook
    /// @param orderType Type of order (Buy/Sell)
    /// @param executionType Type of execution (Limit/Market)
    /// @param token Address of the token to trade
    /// @param amount Amount of tokens to trade
    /// @param price For limit orders: exact price, For market orders: max price (buy) or min price (sell)
    /// @param ttl Time-to-live in seconds for the order
    /// @dev For buy orders, requires ETH to be sent with the transaction
    /// @dev For sell orders, requires token approval
    /// @return uint256 ID of the created order
    function createOrder(
        OrderType orderType,
        OrderExecutionType executionType,
        address token,
        uint256 amount,
        uint256 price,
        uint256 ttl
    ) external payable validToken(token) nonReentrant returns (uint256) {
        require(amount > 0, "Amount must be greater than 0");
        require(price > 0, "Invalid price range");
        require(ttl > 0, "TTL must be greater than 0");
        require(ttl <= maxOrderTtl, "TTL too long");

        // Normalize token amount to 18 decimals for consistent price calculations
        uint256 normalizedAmount = normalizeTo18Decimals(amount, token);
        uint256 totalCost = (normalizedAmount * price) / 1e18;
        require(totalCost >= minOrderSize, "Order too small");
        require(totalCost <= maxOrderSize, "Order too large");

        // For buy orders, require ETH payment including potential fee
        if (orderType == OrderType.Buy) {
            require(msg.value >= totalCost, "Insufficient ETH sent");
        } else {
            IERC20(token).safeTransferFrom(msg.sender, address(this), amount);
        }

        uint256 orderId = _orderIdCounter;
        _orderIdCounter++;

        Order memory newOrder = Order({
            orderId: orderId,
            owner: msg.sender,
            orderType: orderType,
            executionType: executionType,
            token: token,
            amount: normalizedAmount, // Store normalized amount for calculations
            price: price,
            filledAmount: 0,
            expirationTime: block.timestamp + ttl,
            status: OrderStatus.Active
        });

        orders[orderId] = newOrder;

        // Add to the appropriate queue based on execution type
        _addOrderToQueue(orderId, token, orderType, executionType);

        emit OrderCreated(
            orderId,
            msg.sender,
            orderType,
            executionType,
            token,
            amount, // Emit original amount for transparency
            price,
            newOrder.expirationTime,
            totalCost
        );

        // Return excess ETH for buy orders
        if (orderType == OrderType.Buy && msg.value > totalCost) {
            uint256 excess = msg.value - totalCost;
            (bool success, ) = msg.sender.call{value: excess}("");
            require(success, "ETH return failed");
        }

        return orderId;
    }

    /// @notice Cancels an active order
    /// @param orderId ID of the order to cancel
    /// @dev Only the order owner can cancel their order
    /// @dev Refunds ETH for buy orders and tokens for sell orders
    function cancelOrder(
        uint256 orderId
    ) external nonReentrant orderExists(orderId) onlyOrderOwner(orderId) {
        Order storage order = orders[orderId];
        require(order.status == OrderStatus.Active, "Order not active");
        require(!isOrderExpired(orderId), "Order expired");

        order.status = OrderStatus.Cancelled;
        // If it was a buy order, return the ETH including potential fee
        if (order.orderType == OrderType.Buy) {
            uint256 remainingAmount = order.amount - order.filledAmount;
            if (remainingAmount > 0) {
                uint256 refundAmount = (remainingAmount * order.price) / 1e18;
                require(
                    address(this).balance >= refundAmount,
                    "Insufficient ETH in contract"
                );
                (bool success, ) = order.owner.call{value: refundAmount}("");
                require(success, "ETH refund failed");
            }
        }
        // If it was a sell order, return the tokens
        else {
            uint256 remainingAmount = order.amount - order.filledAmount;
            if (remainingAmount > 0) {
                // Denormalize the remaining amount back to token decimals
                uint256 actualRemainingAmount = denormalizeFrom18Decimals(
                    remainingAmount,
                    order.token
                );
                IERC20(order.token).safeTransfer(
                    order.owner,
                    actualRemainingAmount
                );
            }
        }

        bytes32 queueKey = _getQueueKey(
            order.token,
            order.orderType,
            order.executionType
        );
        _removeOrderFromLinkedQueue(queueKey, orderId);

        emit OrderCancelled(orderId);
    }

    /// @notice Marks an expired order as expired and handles refunds
    /// @param orderId ID of the expired order to clean up
    /// @dev Anyone can call this function for expired orders
    /// @dev Refunds tokens for unfilled sell orders and ETH for unfilled buy orders
    function cleanupExpiredOrder(
        uint256 orderId
    ) external nonReentrant orderExists(orderId) {
        Order storage order = orders[orderId];
        require(order.status == OrderStatus.Active, "Order not active");
        require(isOrderExpired(orderId), "Order not expired");

        order.status = OrderStatus.Expired;

        // If it was a sell order, return the tokens
        if (order.orderType == OrderType.Sell) {
            uint256 remainingAmount = order.amount - order.filledAmount;
            if (remainingAmount > 0) {
                // Denormalize the remaining amount back to token decimals
                uint256 actualRemainingAmount = denormalizeFrom18Decimals(
                    remainingAmount,
                    order.token
                );
                IERC20(order.token).safeTransfer(
                    order.owner,
                    actualRemainingAmount
                );
            }
        }

        if (order.orderType == OrderType.Buy) {
            uint256 remainingAmount = order.amount - order.filledAmount;
            if (remainingAmount > 0) {
                uint256 refundAmount = (remainingAmount * order.price) / 1e18;
                require(
                    address(this).balance >= refundAmount,
                    "Insufficient ETH in contract"
                );
                // Refund the ETH
                (bool success, ) = payable(order.owner).call{
                    value: refundAmount
                }("");
                require(success, "ETH refund failed");
            }
        }

        bytes32 queueKey = _getQueueKey(
            order.token,
            order.orderType,
            order.executionType
        );
        _removeOrderFromLinkedQueue(queueKey, orderId);

        emit OrderExpired(orderId);
    }

    /// @notice Fulfills multiple matched limit orders
    /// @param matches Array of OrderMatch structs containing match details
    /// @dev Only whitelisted fulfillers can call this function
    /// @dev All orders in matches must be limit orders
    /// @dev This function matches buy and sell orders against each other
    function fulfillLimitOrders(
        OrderMatch[] calldata matches
    ) external nonReentrant onlyAuthorizedFulfiller {
        require(matches.length > 0, "No order matches to fulfill");

        for (uint256 i = 0; i < matches.length; i++) {
            _fulfillLimitOrders(matches[i]);
        }
    }

    /// @notice Fulfills multiple matched market orders through order matching
    /// @param matches Array of OrderMatch structs containing match details
    /// @param executionPrices Array of execution prices for each match
    /// @dev Only whitelisted fulfillers can call this function
    /// @dev All orders in matches must be market orders
    /// @dev This function matches buy and sell orders against each other
    function fulfillMarketOrders(
        OrderMatch[] calldata matches,
        uint256[] calldata executionPrices
    ) external nonReentrant onlyAuthorizedFulfiller {
        require(matches.length > 0, "No order matches to fulfill");
        require(
            matches.length == executionPrices.length,
            "Mismatched arrays length"
        );

        for (uint256 i = 0; i < matches.length; i++) {
            _fulfillMarketOrders(matches[i], executionPrices[i]);
        }
    }

    /// @notice Internal function to fulfill a matched pair of limit orders
    /// @param _match OrderMatch struct containing the match details
    /// @dev Handles the transfer of ETH and tokens between parties
    /// @dev Allows partial fills of either order
    function _fulfillLimitOrders(OrderMatch memory _match) internal {
        Order storage buyOrder = orders[_match.buyOrderId];
        Order storage sellOrder = orders[_match.sellOrderId];

        // Validate orders
        require(
            buyOrder.status == OrderStatus.Active &&
                sellOrder.status == OrderStatus.Active,
            "Orders must be active"
        );
        require(
            !isOrderExpired(_match.buyOrderId) &&
                !isOrderExpired(_match.sellOrderId),
            "1 of the orders expired"
        );
        require(
            buyOrder.orderType == OrderType.Buy &&
                sellOrder.orderType == OrderType.Sell,
            "Invalid order types"
        );
        require(buyOrder.token == sellOrder.token, "Token mismatch");
        require(
            buyOrder.owner != sellOrder.owner,
            "Seller and buyer cannot be the same"
        );
        require(
            buyOrder.executionType == OrderExecutionType.Limit &&
                sellOrder.executionType == OrderExecutionType.Limit,
            "Not limit orders"
        );

        // Handle different fulfillment types
        _fulfillLimitOrdersMatching(_match);
    }

    /// @notice Internal function to fulfill limit orders through matching
    /// @param _match OrderMatch struct containing the match details
    function _fulfillLimitOrdersMatching(OrderMatch memory _match) internal {
        Order storage buyOrder = orders[_match.buyOrderId];
        Order storage sellOrder = orders[_match.sellOrderId];

        require(
            buyOrder.price >= sellOrder.price,
            "Price mismatch for limit orders"
        );

        // Calculate actual fill amount based on remaining amounts
        uint256 buyRemaining = buyOrder.amount - buyOrder.filledAmount;
        uint256 sellRemaining = sellOrder.amount - sellOrder.filledAmount;
        uint256 actualFillAmount = _match.fillAmount;

        // Adjust fill amount if it exceeds either order's remaining amount
        if (actualFillAmount > buyRemaining) {
            actualFillAmount = buyRemaining;
        }
        if (actualFillAmount > sellRemaining) {
            actualFillAmount = sellRemaining;
        }

        require(actualFillAmount > 0, "No amount to fill");

        // Calculate token amounts and fees
        uint256 tokenAmount = actualFillAmount;
        uint256 paymentAmount = (actualFillAmount * sellOrder.price) / 1e18; // Use sell price for limit orders

        // Calculate and collect fees from both buyer and seller parties
        uint256 buyerFee = _collectFee(paymentAmount);
        uint256 sellerFee = _collectFee(paymentAmount);

        // Calculate final amounts after fees
        uint256 sellerPayment = paymentAmount - sellerFee;

        // Execute transfers
        // 1. Transfer ETH from contract to seller (minus seller fee)
        (bool success, ) = sellOrder.owner.call{value: sellerPayment}("");
        require(success, "ETH transfer to seller failed");

        // 2. Transfer traded tokens from contract to buyer
        {
            uint256 tokenFee = (buyerFee * 1e18) / sellOrder.price;
            uint256 actualTokenAmount = denormalizeFrom18Decimals(
                tokenAmount,
                sellOrder.token
            );
            uint256 actualTokenFee = denormalizeFrom18Decimals(
                tokenFee,
                sellOrder.token
            );
            IERC20(sellOrder.token).safeTransfer(
                buyOrder.owner,
                actualTokenAmount - actualTokenFee
            );
        }

        // Update order states
        buyOrder.filledAmount += actualFillAmount;
        sellOrder.filledAmount += actualFillAmount;

        // Return excess ETH to buyer if using a lower sell price
        if (buyOrder.price > sellOrder.price) {
            uint256 savedAmount = (actualFillAmount *
                (buyOrder.price - sellOrder.price)) / 1e18;
            (success, ) = buyOrder.owner.call{value: savedAmount}("");
            require(success, "ETH savings return failed");
        }

        // Update order statuses and remove from queues if fully filled
        _updateOrderStatus(_match.buyOrderId, actualFillAmount);
        _updateOrderStatus(_match.sellOrderId, actualFillAmount);
    }

    /// @notice Internal function to fulfill a matched pair of market orders
    /// @param _match OrderMatch struct containing the match details
    /// @param executionPrice The price at which the orders will be executed
    /// @dev Handles the transfer of ETH and tokens between parties
    /// @dev Allows partial fills of either order
    function _fulfillMarketOrders(
        OrderMatch memory _match,
        uint256 executionPrice
    ) internal {
        Order storage buyOrder = orders[_match.buyOrderId];
        Order storage sellOrder = orders[_match.sellOrderId];

        // Validate orders
        require(
            buyOrder.status == OrderStatus.Active &&
                sellOrder.status == OrderStatus.Active,
            "Orders must be active"
        );
        require(
            !isOrderExpired(_match.buyOrderId) &&
                !isOrderExpired(_match.sellOrderId),
            "Orders expired"
        );
        require(
            buyOrder.orderType == OrderType.Buy &&
                sellOrder.orderType == OrderType.Sell,
            "Invalid order types"
        );
        require(buyOrder.token == sellOrder.token, "Token mismatch");
        require(
            (buyOrder.executionType == OrderExecutionType.Market ||
                sellOrder.executionType == OrderExecutionType.Market),
            "Not market orders"
        );

        // Handle different fulfillment types
        _fulfillMarketOrdersMatching(_match, executionPrice);
    }

    /// @notice Internal function to fulfill market orders through matching
    /// @param _match OrderMatch struct containing the match details
    /// @param executionPrice The price at which the orders will be executed
    function _fulfillMarketOrdersMatching(
        OrderMatch memory _match,
        uint256 executionPrice
    ) internal {
        Order storage buyOrder = orders[_match.buyOrderId];
        Order storage sellOrder = orders[_match.sellOrderId];

        // Validate execution price against market price
        require(
            validateExecutionPrice(buyOrder.token, executionPrice),
            "Execution price deviates too much from market price"
        );

        // Validate execution price
        if (buyOrder.executionType == OrderExecutionType.Market) {
            require(
                executionPrice <= buyOrder.price,
                "Execution price exceeds buyer's max price"
            );
        }
        if (sellOrder.executionType == OrderExecutionType.Market) {
            require(
                executionPrice >= sellOrder.price,
                "Execution price below seller's min price"
            );
        }

        // Calculate actual fill amount based on remaining amounts
        uint256 buyRemaining = buyOrder.amount - buyOrder.filledAmount;
        uint256 sellRemaining = sellOrder.amount - sellOrder.filledAmount;
        uint256 actualFillAmount = _match.fillAmount;

        // Adjust fill amount if it exceeds either order's remaining amount
        if (actualFillAmount > buyRemaining) {
            actualFillAmount = buyRemaining;
        }
        if (actualFillAmount > sellRemaining) {
            actualFillAmount = sellRemaining;
        }

        require(actualFillAmount > 0, "No amount to fill");

        // Calculate token amounts and fees
        uint256 tokenAmount = actualFillAmount;
        uint256 paymentAmount = (actualFillAmount * executionPrice) / 1e18;

        // Calculate and collect fees from both buyer and seller parties
        uint256 buyerFee = _collectFee(paymentAmount);
        uint256 sellerFee = _collectFee(paymentAmount);

        // Calculate final amounts after fees
        uint256 sellerPayment = paymentAmount - sellerFee;

        // Execute transfers
        // 1. Transfer ETH from contract to seller (minus seller fee)
        (bool success, ) = sellOrder.owner.call{value: sellerPayment}("");
        require(success, "ETH transfer to seller failed");

        // 2. Transfer traded tokens from contract to buyer
        {
            uint256 tokenFee = (buyerFee * 1e18) / executionPrice;
            uint256 actualTokenAmount = denormalizeFrom18Decimals(
                tokenAmount,
                sellOrder.token
            );
            uint256 actualTokenFee = denormalizeFrom18Decimals(
                tokenFee,
                sellOrder.token
            );
            IERC20(sellOrder.token).safeTransfer(
                buyOrder.owner,
                actualTokenAmount - actualTokenFee
            );
        }

        // Update order states
        buyOrder.filledAmount += actualFillAmount;
        sellOrder.filledAmount += actualFillAmount;

        // Update order statuses and remove from queues if fully filled
        _updateOrderStatus(_match.buyOrderId, actualFillAmount);
        _updateOrderStatus(_match.sellOrderId, actualFillAmount);
    }

    /// @notice Fulfills multiple orders through the market maker pool
    /// @param orderIds Array of order IDs to fulfill
    /// @param fillAmounts Array of fill amounts for each order
    /// @dev Only whitelisted fulfillers can call this function
    function fulfillOrdersWithMarketMaker(
        uint256[] calldata orderIds,
        uint256[] calldata fillAmounts
    ) external nonReentrant onlyAuthorizedFulfiller {
        require(orderIds.length > 0, "No orders to fulfill");
        require(
            orderIds.length == fillAmounts.length,
            "Mismatched arrays length"
        );

        for (uint256 i = 0; i < orderIds.length; i++) {
            require(fillAmounts[i] > 0, "Fill amount must be greater than 0");
            _fulfillOrderWithMarketMaker(orderIds[i], fillAmounts[i]);
        }
    }

    /// @notice Internal function to fulfill a single order through the market maker pool
    /// @param orderId ID of the order to fulfill
    /// @param fillAmount Amount of tokens to fill
    function _fulfillOrderWithMarketMaker(
        uint256 orderId,
        uint256 fillAmount
    ) internal {
        Order storage order = orders[orderId];

        // Validate order
        require(order.status == OrderStatus.Active, "Order not active");
        require(!isOrderExpired(orderId), "Order expired");

        // Get market maker pool address from registry
        address marketMakerPool = gradientRegistry.marketMakerPool();
        require(marketMakerPool != address(0), "Market maker pool not set");

        // Calculate actual fill amount based on remaining amount
        uint256 remainingAmount = order.amount - order.filledAmount;
        uint256 actualFillAmount = fillAmount > remainingAmount
            ? remainingAmount
            : fillAmount;

        require(actualFillAmount > 0, "No amount to fill");

        // Calculate payment amount and fees
        uint256 paymentAmount = (actualFillAmount * order.price) / 1e18;

        if (order.orderType == OrderType.Buy) {
            // Buy order from order to get tokens from market maker pool
            uint256 epoch = IGradientMarketMakerPool(marketMakerPool)
                .getCurrentTokenEpoch(order.token);
            // For buy orders: orderbook sends ETH to market maker, receives tokens
            // Execute buy order - Orderbook sends ETH, receives tokens
            IGradientMarketMakerPool(marketMakerPool).executeBuyOrder{
                value: paymentAmount
            }(order.token, paymentAmount, actualFillAmount);

            // Distribute market maker fee from already collected fees
            uint256 fee = (paymentAmount * feePercentage) / DIVISOR;
            uint256 feeForPool = (fee * mmFeeDistributionPercentage) / DIVISOR;
            totalFeesCollected -= feeForPool;
            if (feeForPool > 0) {
                IGradientMarketMakerPool(marketMakerPool).distributePoolFee{
                    value: feeForPool
                }(order.token, epoch, false);
                emit FeeDistributedToPool(
                    marketMakerPool,
                    order.token,
                    epoch,
                    feeForPool,
                    fee
                );
            }
            // Denormalize the amount before transferring tokens
            uint256 actualTokenAmount = denormalizeFrom18Decimals(
                actualFillAmount,
                order.token
            );
            IERC20(order.token).safeTransfer(order.owner, actualTokenAmount);
        } else {
            // Sell order from order to get ETH from market maker pool
            uint256 epoch = IGradientMarketMakerPool(marketMakerPool)
                .getCurrentETHEpoch(order.token);

            // Denormalize the amount for token approval
            uint256 actualTokenAmount = denormalizeFrom18Decimals(
                actualFillAmount,
                order.token
            );

            // Approve tokens to market maker pool
            IERC20(order.token).approve(marketMakerPool, actualTokenAmount);

            // Execute sell order - Orderbook sends tokens, receives ETH
            IGradientMarketMakerPool(marketMakerPool).executeSellOrder(
                order.token,
                paymentAmount,
                actualTokenAmount
            );

            // Collect fee from ETH received
            uint256 fee = _collectFee(paymentAmount);
            uint256 finalPayment = paymentAmount - fee;

            // Distribute fees to market maker pool
            uint256 feeForPool = (fee * mmFeeDistributionPercentage) / DIVISOR;
            totalFeesCollected -= feeForPool;
            if (feeForPool > 0) {
                IGradientMarketMakerPool(marketMakerPool).distributePoolFee{
                    value: feeForPool
                }(order.token, epoch, true); // Distribute to ETH pool for sell orders
                emit FeeDistributedToPool(
                    marketMakerPool,
                    order.token,
                    epoch,
                    feeForPool,
                    fee
                );
            }

            // Transfer ETH to seller (minus fee)
            (bool success, ) = order.owner.call{value: finalPayment}("");
            require(success, "ETH transfer to seller failed");
        }

        // Update order state
        order.filledAmount += actualFillAmount;

        // Update order status
        _updateOrderStatus(orderId, actualFillAmount);

        emit OrderFulfilledByMarketMaker(
            orderId,
            marketMakerPool,
            actualFillAmount,
            order.price
        );
    }

    /// @notice Allows users to fulfill their own order via AMM
    /// @param orderId ID of the order to fulfill
    /// @param fillAmount Amount of tokens to fill
    /// @param minAmountOut Minimum amount to receive (slippage protection)
    /// @dev Only the order owner can call this function
    /// @dev Uses FallbackExecutor to find the best DEX and execute the trade
    function fulfillOwnOrderWithAMM(
        uint256 orderId,
        uint256 fillAmount,
        uint256 minAmountOut
    ) external nonReentrant orderExists(orderId) onlyOrderOwner(orderId) {
        require(fillAmount > 0, "Fill amount must be greater than 0");

        Order storage order = orders[orderId];
        require(order.status == OrderStatus.Active, "Order not active");

        // Calculate actual fill amount based on remaining amount
        uint256 remainingAmount = order.amount - order.filledAmount;
        uint256 actualFillAmount = fillAmount > remainingAmount
            ? remainingAmount
            : fillAmount;
        require(actualFillAmount > 0, "No amount to fill");

        // Calculate payment amount and fees
        uint256 paymentAmount = (actualFillAmount * order.price) / 1e18;

        // Get FallbackExecutor from registry
        address fallbackExecutor = gradientRegistry.fallbackExecutor();
        require(fallbackExecutor != address(0), "FallbackExecutor not set");

        // Execute trade through FallbackExecutor
        if (order.orderType == OrderType.Buy) {
            // Calculate and collect buyer fee from deposited ETH
            uint256 buyerFee = _collectFee(paymentAmount);

            // Execute the buy trade directly through FallbackExecutor
            uint256 tokensReceived = IFallbackExecutor(fallbackExecutor)
                .executeTrade{value: paymentAmount}(
                order.token,
                paymentAmount,
                minAmountOut,
                true // isBuy = true
            );

            // Calculate token fee and deduct from received tokens
            uint256 tokenFee = (buyerFee * 1e18) / order.price;
            uint256 actualTokenFee = denormalizeFrom18Decimals(
                tokenFee,
                order.token
            );
            IERC20(order.token).safeTransfer(
                order.owner,
                tokensReceived - actualTokenFee
            );
        } else {
            // Denormalize the amount for token approval and transfer
            uint256 actualTokenAmount = denormalizeFrom18Decimals(
                actualFillAmount,
                order.token
            );

            // Approve tokens to FallbackExecutor
            IERC20(order.token).approve(fallbackExecutor, actualTokenAmount);

            // Execute the sell trade
            uint256 ethReceived = IFallbackExecutor(fallbackExecutor)
                .executeTrade(
                    order.token,
                    actualTokenAmount,
                    minAmountOut,
                    false // isBuy = false
                );

            uint256 ammFee = _collectFee(ethReceived);

            // Transfer received ETH to order owner (minus fee)
            uint256 ethForUser = ethReceived - ammFee;
            (bool success, ) = order.owner.call{value: ethForUser}("");
            require(success, "ETH transfer to seller failed");
        }
        order.filledAmount += actualFillAmount;

        // Update order status
        _updateOrderStatus(orderId, actualFillAmount);
    }

    /// @notice Internal function to update order status
    /// @param orderId ID of the order to update
    /// @param actualFillAmount Amount of tokens/ETH that was filled
    function _updateOrderStatus(
        uint256 orderId,
        uint256 actualFillAmount
    ) internal {
        Order storage order = orders[orderId];
        if (order.filledAmount == order.amount) {
            order.status = OrderStatus.Filled;
            bytes32 queueKey = _getQueueKey(
                order.token,
                order.orderType,
                order.executionType
            );
            _removeOrderFromLinkedQueue(queueKey, orderId);

            emit OrderFulfilled(orderId, actualFillAmount);
        } else {
            emit OrderPartiallyFulfilled(
                orderId,
                actualFillAmount,
                order.amount - order.filledAmount
            );
        }
    }

